function defineBot(manifest) {
  if (!manifest || typeof manifest.name !== "string" || manifest.name.length === 0 || typeof manifest.create !== "function") {
    throw new Error("defineBot requires { name, create }");
  }
  return { __rs2b0tManifest: 1, ...manifest };
}

// src/bot/api/events/EventBus.ts
class EventBusImpl {
  listeners = new Map;
  off(event, cb) {
    const hostEvents = globalThis.__rs2b0t?.events;
    if (hostEvents && hostEvents !== this && typeof hostEvents.off === "function") {
      hostEvents.off(event, cb);
      return;
    }
    this.listeners.get(event)?.delete(cb);
  }
  on(event, cb) {
    const hostEvents = globalThis.__rs2b0t?.events;
    if (hostEvents && hostEvents !== this && typeof hostEvents.on === "function") {
      return hostEvents.on(event, cb);
    }
    let set = this.listeners.get(event);
    if (!set) {
      set = new Set;
      this.listeners.set(event, set);
    }
    set.add(cb);
    return () => set.delete(cb);
  }
  emit(event, payload) {
    const set = this.listeners.get(event);
    if (!set) {
      return;
    }
    for (const cb of set) {
      try {
        cb(payload);
      } catch (err) {
        console.error(`[rs2b0t] '${event}' listener error`, err);
      }
    }
  }
}
var bus = new EventBusImpl;

// src/bot/geometry/Tile.ts
class Tile {
  x;
  z;
  level;
  constructor(x, z, level = 0) {
    this.x = x;
    this.z = z;
    this.level = level;
  }
  static from(tile) {
    return new Tile(tile.x, tile.z, tile.level);
  }
  distanceTo(other) {
    const xz = Math.max(Math.abs(this.x - other.x), Math.abs(this.z - other.z));
    if ((this.level ?? 0) !== (other.level ?? 0)) {
      return 1e6 + xz;
    }
    return xz;
  }
  translate(dx, dz) {
    return new Tile(this.x + dx, this.z + dz, this.level);
  }
  equals(other) {
    return this.x === other.x && this.z === other.z && this.level === other.level;
  }
  toString() {
    return `(${this.x}, ${this.z}, ${this.level})`;
  }
}

