function boxId() {
  if (typeof location === "undefined") {
    return "";
  }
  return new URLSearchParams(location.search).get("box") ?? "";
}
function boxKey(suffix) {
  const id = boxId();
  return id ? `rs2b0t:${id}:${suffix}` : `rs2b0t:${suffix}`;
}

