// src/client/config/FloType.ts
class FloType {
  static numDefinitions = 0;
  static list = [];
  colour = 0;
  texture = -1;
  overlay = false;
  occlude = true;
  debugname = "";
  hue = 0;
  saturation = 0;
  lightness = 0;
  chroma = 0;
  underlayHue = 0;
  overlayHsl = 0;
  static init(config) {
    const dat = new Packet(config.read("flo.dat"));
    this.numDefinitions = dat.g2();
    this.list = new Array(this.numDefinitions);
    for (let id = 0;id < this.numDefinitions; id++) {
      if (!this.list[id]) {
        this.list[id] = new FloType;
      }
      this.list[id].decode(dat);
    }
  }
  decode(dat) {
    while (true) {
      const code = dat.g1();
      if (code === 0) {
        break;
      }
      if (code === 1) {
        this.colour = dat.g3();
        this.getHsl(this.colour);
      } else if (code === 2) {
        this.texture = dat.g1();
      } else if (code === 3) {
        this.overlay = true;
      } else if (code === 5) {
        this.occlude = false;
      } else if (code === 6) {
        this.debugname = dat.gjstr();
      } else {
        console.log("Error unrecognised config code: ", code);
      }
    }
  }
  getHsl(rgb) {
    const red = (rgb >> 16 & 255) / 256;
    const green = (rgb >> 8 & 255) / 256;
    const blue = (rgb & 255) / 256;
    let min = red;
    if (green < red) {
      min = green;
    }
    if (blue < min) {
      min = blue;
    }
    let max2 = red;
    if (green > red) {
      max2 = green;
    }
    if (blue > max2) {
      max2 = blue;
    }
    let h = 0;
    let s = 0;
    const l = (min + max2) / 2;
    if (min !== max2) {
      if (l < 0.5) {
        s = (max2 - min) / (max2 + min);
      }
      if (l >= 0.5) {
        s = (max2 - min) / (2 - max2 - min);
      }
      if (red === max2) {
        h = (green - blue) / (max2 - min);
      } else if (green === max2) {
        h = (blue - red) / (max2 - min) + 2;
      } else if (blue === max2) {
        h = (red - green) / (max2 - min) + 4;
      }
    }
    h /= 6;
    this.hue = h * 256 | 0;
    this.saturation = s * 256 | 0;
    this.lightness = l * 256 | 0;
    if (this.saturation < 0) {
      this.saturation = 0;
    } else if (this.saturation > 255) {
      this.saturation = 255;
    }
    if (this.lightness < 0) {
      this.lightness = 0;
    } else if (this.lightness > 255) {
      this.lightness = 255;
    }
    if (l > 0.5) {
      this.chroma = (1 - l) * s * 512 | 0;
    } else {
      this.chroma = l * s * 512 | 0;
    }
    if (this.chroma < 1) {
      this.chroma = 1;
    }
    this.underlayHue = h * this.chroma | 0;
    let hue = this.hue + (Math.random() * 16 | 0) - 8;
    if (hue < 0) {
      hue = 0;
    } else if (hue > 255) {
      hue = 255;
    }
    let saturation = this.saturation + (Math.random() * 48 | 0) - 24;
    if (saturation < 0) {
      saturation = 0;
    } else if (saturation > 255) {
      saturation = 255;
    }
    let lightness = this.lightness + (Math.random() * 48 | 0) - 24;
    if (lightness < 0) {
      lightness = 0;
    } else if (lightness > 255) {
      lightness = 255;
    }
    this.overlayHsl = FloType.getTable(hue, saturation, lightness);
  }
  static getTable(hue, saturation, lightness) {
    if (lightness > 179) {
      saturation = saturation / 2 | 0;
    }
    if (lightness > 192) {
      saturation = saturation / 2 | 0;
    }
    if (lightness > 217) {
      saturation = saturation / 2 | 0;
    }
    if (lightness > 243) {
      saturation = saturation / 2 | 0;
    }
    return ((hue / 4 | 0) << 10) + ((saturation / 32 | 0) << 7) + (lightness / 2 | 0);
  }
}

// src/client/config/SeqType.ts
class SeqType {
  static numDefinitions = 0;
  static list = [];
  static STRICT = false;
  id = -1;
  numFrames = 0;
  frames = null;
  iframes = null;
  delay = null;
  loops = -1;
  walkmerge = null;
  reachforward = false;
  priority = 5;
  replaceheldleft = -1;
  replaceheldright = -1;
  maxloops = 99;
  preanim_move = -1;
  postanim_move = -1;
  duplicatebehaviour = -1;
  static init(config) {
    const dat = new Packet(config.read("seq.dat"));
    this.numDefinitions = dat.g2();
    this.list = new Array(this.numDefinitions);
    for (let id = 0;id < this.numDefinitions; id++) {
      if (!this.list[id]) {
        this.list[id] = new SeqType;
      }
      this.list[id].id = id;
      this.list[id].decode(dat);
    }
  }
  getDelay(frame) {
    if (!this.delay || !this.frames) {
      return 0;
    }
    let delay = this.delay[frame];
    if (delay === 0) {
      const transform = AnimFrame.get(this.frames[frame]);
      if (transform != null) {
        delay = this.delay[frame] = transform.delay;
      }
    }
    if (delay === 0) {
      delay = 1;
    }
    return delay;
  }
  decode(dat) {
    while (true) {
      const code = dat.g1();
      if (code === 0) {
        break;
      }
      if (code === 1) {
        this.numFrames = dat.g1();
        this.frames = new Int16Array(this.numFrames);
        this.iframes = new Int16Array(this.numFrames);
        this.delay = new Int16Array(this.numFrames);
        for (let i2 = 0;i2 < this.numFrames; i2++) {
          this.frames[i2] = dat.g2();
          this.iframes[i2] = dat.g2();
          if (this.iframes[i2] === 65535) {
            this.iframes[i2] = -1;
          }
          this.delay[i2] = dat.g2();
        }
      } else if (code === 2) {
        this.loops = dat.g2();
      } else if (code === 3) {
        const count = dat.g1();
        this.walkmerge = new Int32Array(count + 1);
        for (let i2 = 0;i2 < count; i2++) {
          this.walkmerge[i2] = dat.g1();
        }
        this.walkmerge[count] = 9999999;
      } else if (code === 4) {
        this.reachforward = true;
      } else if (code === 5) {
        this.priority = dat.g1();
      } else if (code === 6) {
        this.replaceheldleft = dat.g2();
      } else if (code === 7) {
        this.replaceheldright = dat.g2();
      } else if (code === 8) {
        this.maxloops = dat.g1();
      } else if (code === 9) {
        this.preanim_move = dat.g1();
      } else if (code === 10) {
        this.postanim_move = dat.g1();
      } else if (code === 11) {
        this.duplicatebehaviour = dat.g1();
      } else if (SeqType.STRICT) {
        throw new Error(`SeqType ${this.id}: unknown config opcode ${code}`);
      }
    }
    if (this.numFrames === 0) {
      this.numFrames = 1;
      this.frames = new Int16Array(1);
      this.frames[0] = -1;
      this.iframes = new Int16Array(1);
      this.iframes[0] = -1;
      this.delay = new Int16Array(1);
      this.delay[0] = -1;
    }
    if (this.preanim_move === -1) {
      if (this.walkmerge === null) {
        this.preanim_move = 0 /* DELAYMOVE */;
      } else {
        this.preanim_move = 2 /* MERGE */;
      }
    }
    if (this.postanim_move === -1) {
      if (this.walkmerge === null) {
        this.postanim_move = 0 /* DELAYMOVE */;
      } else {
        this.postanim_move = 2 /* MERGE */;
      }
    }
  }
}

// src/client/dash3d/ClientLocAnim.ts
class ClientLocAnim extends ModelSource {
  index;
  shape;
  angle;
  heightSW;
  heightSE;
  heightNE;
  heightNW;
  anim;
  animFrame;
  animCycle;
  constructor(index, shape, angle, heightSW, heightSE, heightNE, heightNW, seq, randomFrame) {
    super();
    this.index = index;
    this.shape = shape;
    this.angle = angle;
    this.heightSW = heightSW;
    this.heightSE = heightSE;
    this.heightNE = heightNE;
    this.heightNW = heightNW;
    this.anim = SeqType.list[seq];
    this.animFrame = 0;
    this.animCycle = Client.loopCycle;
    if (randomFrame && this.anim.loops !== -1) {
      this.animFrame = Math.random() * this.anim.numFrames | 0;
      this.animCycle -= Math.random() * this.anim.getDelay(this.animFrame) | 0;
    }
  }
  getTempModel() {
    if (this.anim) {
      let delta = Client.loopCycle - this.animCycle;
      if (delta > 100 && this.anim.loops > 0) {
        delta = 100;
      }
      while (delta > this.anim.getDelay(this.animFrame)) {
        delta -= this.anim.getDelay(this.animFrame);
        this.animFrame++;
        if (this.animFrame < this.anim.numFrames) {
          continue;
        }
        this.animFrame -= this.anim.loops;
        if (this.animFrame < 0 || this.animFrame >= this.anim.numFrames) {
          this.anim = null;
          break;
        }
      }
      this.animCycle = Client.loopCycle - delta;
    }
    let frame = -1;
    if (this.anim && this.anim.frames && typeof this.anim.frames[this.animFrame] !== "undefined") {
      frame = this.anim.frames[this.animFrame];
    }
    const loc = LocType.list(this.index);
    return loc.getModel(this.shape, this.angle, this.heightSW, this.heightSE, this.heightNE, this.heightNW, frame);
  }
}

