// src/client/dash3d/MapSpotAnim.ts
class MapSpotAnim extends ModelSource {
  type;
  level;
  x;
  z;
  y;
  startCycle;
  animComplete = false;
  animFrame = 0;
  animCycle = 0;
  constructor(id, level, x2, z, y, cycle, delay) {
    super();
    this.type = SpotType.list[id];
    this.level = level;
    this.x = x2;
    this.z = z;
    this.y = y;
    this.startCycle = cycle + delay;
  }
  update(delta) {
    if (!this.type.seq) {
      return;
    }
    for (this.animCycle += delta;this.animCycle > this.type.seq.getDelay(this.animFrame); ) {
      this.animCycle -= this.type.seq.getDelay(this.animFrame) + 1;
      this.animFrame++;
      if (this.animFrame >= this.type.seq.numFrames) {
        this.animFrame = 0;
        this.animComplete = true;
      }
    }
  }
  getTempModel() {
    const tmp = this.type.getTempModel2();
    if (!tmp) {
      return null;
    }
    let frame = -1;
    if (this.type.seq && this.type.seq.frames) {
      frame = this.type.seq.frames[this.animFrame];
    }
    const model = Model.copyForAnim(tmp, true, AnimFrame.animateTransparencies(frame), false);
    if (!this.animComplete) {
      model.prepareAnim();
      model.animate(frame);
      model.labelFaces = null;
      model.labelVertices = null;
    }
    if (this.type.resizeh !== 128 || this.type.resizev !== 128) {
      model.resize(this.type.resizeh, this.type.resizev, this.type.resizeh);
    }
    if (this.type.angle !== 0) {
      if (this.type.angle === 90) {
        model.rotate90();
      } else if (this.type.angle === 180) {
        model.rotate90();
        model.rotate90();
      } else if (this.type.angle === 270) {
        model.rotate90();
        model.rotate90();
        model.rotate90();
      }
    }
    model.calculateNormals(64 + this.type.ambient, 850 + this.type.contrast, -30, -50, -30, true);
    return model;
  }
}

// src/client/util/JavaRandom.ts
var p2_16 = 65536;
var p2_24 = 16777216;
var p2_27 = 134217728;
var p2_31 = 2147483648;
var p2_32 = 4294967296;
var p2_48 = 281474976710656;
var p2_53 = Math.pow(2, 53);
var m2_16 = 65535;
