// src/bot/api/bank/bankRules.ts
var COMMON_BANK_LOOT = [
  "uncut",
  "sapphire",
  "emerald",
  "ruby",
  "diamond",
  "opal",
  "jade",
  "topaz",
  "strange fruit",
  "beer",
  "kebab"
];
var RANDOM_EVENT_CASKET_ID = 405;
function matchesCommonBankLoot(name, id = -1) {
  if (id === RANDOM_EVENT_CASKET_ID) {
    return true;
  }
  if (name.length === 0) {
    return false;
  }
  const n = name.toLowerCase();
  return COMMON_BANK_LOOT.some((p) => n.includes(p));
}
function isDisposableGatherJunk(name, id = -1) {
  if (matchesCommonBankLoot(name ?? "", id)) {
    return true;
  }
  const n = (name ?? "").toLowerCase().trim();
  if (n.length === 0) {
    return false;
  }
  return n === "flier" || n === "half a meat pie" || n === "half a redberry pie" || n === "half an apple pie";
}
function depositMatcher(own, includeCommon) {
  return (name, id = -1) => own(name) || includeCommon && matchesCommonBankLoot(name, id);
}

// src/bot/event/webwalk/geometry/arrival.ts
function walkChebyshev(a, b) {
  const xz = chebyshev(a, b);
  return a.level === b.level ? xz : 1e6 + xz;
}
function isArrived(me, dest, radius, probe) {
  if (me.level !== dest.level) {
    return false;
  }
  const dist = chebyshev(me, dest);
  if (dist > radius) {
    return false;
  }
  if (dist === 0) {
    return true;
  }
  if (probe.canReach(dest)) {
    return true;
  }
  if (probe.walkable(dest)) {
    return false;
  }
  return !probe.probeable(dest) || probe.canReachAdjacent(dest);
}

// src/bot/event/webwalk/walkOpening.ts
var ESCAPE_RADIUS = 14;
var TOWARD_SLACK = 4;
function isOpenableObstacle(name, actions2, obstacles) {
  const n = (name ?? "").toLowerCase();
  return obstacles.some((k) => n.includes(k)) && actions2.some((a) => /^open/i.test(a));
}
function openOp(actions2) {
  return actions2.find((a) => /^open/i.test(a)) ?? null;
}
function towardDest(door, here, dest) {
  const cheb = (a, b) => Math.max(Math.abs(a.x - b.x), Math.abs(a.z - b.z));
  return cheb(door, dest) <= cheb(here, dest) + TOWARD_SLACK;
}
async function walkOpening(dest, radius, obstacles, log) {
  for (let seg = 0;seg < 8; seg++) {
    const here2 = Game.tile();
    if (here2 && isArrived(here2, dest, radius, Reachability.arrivalProbe())) {
      return true;
    }
    await Traversal.walkTo(dest, { radius, timeoutMs: 90000, log: (m) => log?.(`  ${m}`) });
    const after = Game.tile();
    if (after && isArrived(after, dest, radius, Reachability.arrivalProbe())) {
      return true;
    }
    const openableInRange = (l) => isOpenableObstacle(l.name, l.actions(), obstacles) && l.distance() <= ESCAPE_RADIUS && Reachability.canReach(l.tile(), { adjacentOk: true });
    const door = Locs.query().where((l) => openableInRange(l)).where((l) => after === null || towardDest(l.tile(), after, dest)).nearest() ?? Locs.query().where((l) => openableInRange(l)).nearest();
    if (!door) {
      return false;
    }
    const dt = door.tile();
    const cur = Game.tile();
    if (cur && dt.distanceTo(cur) > 1) {
      log?.(`walking to ${door.name} at ${dt.x},${dt.z} to open it`);
      await Traversal.walkTo(dt, { radius: 1, timeoutMs: 45000, log: (m) => log?.(`  ${m}`) });
    }
    const shut = Locs.query().where((l) => l.tile().x === dt.x && l.tile().z === dt.z && isOpenableObstacle(l.name, l.actions(), obstacles)).nearest();
    if (!shut) {
      continue;
    }
    const op = openOp(shut.actions());
    log?.(`opening ${shut.name} at ${dt.x},${dt.z}`);
    if (!await shut.interact(op)) {
      await Execution.delayTicks(2);
      continue;
    }
    await Execution.delayUntil(() => {
      const still = Locs.query().where((l) => l.tile().x === dt.x && l.tile().z === dt.z && isOpenableObstacle(l.name, l.actions(), obstacles)).nearest();
      return still === null;
    }, 4000);
  }
  const here = Game.tile();
  return here !== null && isArrived(here, dest, radius, Reachability.arrivalProbe());
}

// src/bot/api/bank/Banking.ts
var NEARBY_BANK_RADIUS = 14;
function openAccess(dest, fallback, log) {
  if (dest?.npcAccess) {
    return Bank.openNpcAccess(dest.npcAccess, log);
  }
  return Bank.openNearestAccess(dest?.access ?? fallback, log);
}
function realBooth(boothName) {
  return Locs.query().name(boothName).where((l) => l.actions().length > 0).nearest();
}
function nearbyUsableBooth(boothName, maxDist) {
  return Locs.query().name(boothName).where((l) => l.actions().length > 0 && l.distance() <= maxDist).nearest();
}
function resolveBankOpenRoute(input) {
  if (input.bankOpen) {
    return "already-open";
  }
  const prefer = input.preferNearby !== false;
  const radius = input.nearbyRadius ?? NEARBY_BANK_RADIUS;
  if (prefer && input.nearbyBoothDist !== null && input.nearbyBoothDist <= radius) {
    return "scene-booth";
  }
  const here = input.here;
  if (prefer && here && input.nearest) {
    const localD = bankDistance(here, input.nearest.tile);
    if (localD <= radius) {
      const stand = input.stand;
      if (!stand || bankDistance(here, stand) > radius) {
        return "local-bank";
      }
    }
  }
  if (input.stand) {
    return "preset-stand";
  }
  return "nearest-fallback";
}
function asTile(t) {
  return t instanceof Tile ? t : new Tile(t.x, t.z, t.level);
}
var Banking = {
  async open(opts = {}) {
    const boothName = opts.boothName ?? "Bank booth";
    const boothOp = opts.boothOp ?? "Use-quickly";
    const log = opts.log ?? (() => {});
    const obstacles = (opts.obstacles ?? []).map((s) => s.trim().toLowerCase()).filter(Boolean);
    const preferNearby = opts.preferNearby !== false;
    const nearbyRadius = opts.nearbyRadius ?? NEARBY_BANK_RADIUS;
    if (Bank.isOpen()) {
      return true;
    }
    const here = Game.tile();
    const boothNear = preferNearby ? nearbyUsableBooth(boothName, nearbyRadius) : null;
    const nearest = here ? nearestBank(here) : null;
    const route = resolveBankOpenRoute({
      bankOpen: false,
      here,
      stand: opts.stand ?? null,
      nearbyBoothDist: boothNear ? boothNear.distance() : null,
      nearest,
      preferNearby,
      nearbyRadius
    });
    if (route === "scene-booth") {
      log(`bank: booth within ${nearbyRadius} — opening here (skip long walk)`);
      return Bank.openNearestAccess({ name: boothName, op: boothOp }, log);
    }
    if (route === "local-bank" && nearest) {
      log(`bank: local ${nearest.name} bank — using it instead of distant preset`);
      await Traversal.walkResilient(asTile(nearest.tile), { radius: 4, timeoutMs: 120000, log });
      return openAccess(nearest, { name: boothName, op: boothOp }, log);
    }
    if (route === "preset-stand" && opts.stand) {
      const stand = asTile(opts.stand);
      if (obstacles.length > 0) {
        await walkOpening(stand, 2, obstacles, log);
      } else {
        await Traversal.walkResilient(stand, { radius: 2, timeoutMs: 120000, log });
      }
      const known = nearestBank(stand);
      if (known && (known.access || known.npcAccess) && bankDistance(stand, known.tile) <= nearbyRadius) {
        log(`bank: ${known.name} uses ${known.npcAccess ? "npc" : "object"} access`);
        return openAccess(known, { name: boothName, op: boothOp }, log);
      }
      return Bank.openBooth(stand, boothName, boothOp, log);
    }
    let destination = null;
    if (!realBooth(boothName)) {
      destination = opts.destination ?? (nearest ? { name: nearest.name, tile: nearest.tile, access: nearest.access, npcAccess: nearest.npcAccess } : null);
      if (destination) {
        log(`no booth in scene — web-walking to the ${destination.name} bank at ${destination.tile}`);
        await Traversal.walkResilient(asTile(destination.tile), { radius: 4, timeoutMs: 120000, log });
      }
    }
    return openAccess(destination, { name: boothName, op: boothOp }, log);
  },
  async bankNearest(opts) {
    const log = opts.log ?? (() => {});
    if (!await Banking.open({
      boothName: opts.boothName,
      boothOp: opts.boothOp,
      destination: opts.destination,
      log
    })) {
      return false;
    }
    await Bank.depositAllMatching(depositMatcher(opts.deposit, opts.commonJunk ?? true));
    await opts.afterDeposit?.();
    await Execution.delayTicks(1);
    if (opts.returnTo) {
      await Traversal.walkResilient(asTile(opts.returnTo), { radius: 6, timeoutMs: 120000, log });
    }
    return true;
  }
};

