// src/bot/event/webwalk/wilderness.ts
var WILDERNESS_SOUTH_Z = 3520;
var WILDERNESS_UNDERGROUND_SOUTH_Z = 9920;
var WILD_X_MIN = 2944;
var WILD_X_MAX = 3391;
