    members: Client.memServer === true,
    skills,
    quests,
    items,
    worn,
    freeSlots: Inventory.free(),
    entranaRestrictedGear,
    canSlashWeb,
    ...wildernessLevel !== undefined ? { wildernessLevel } : {},
