// src/bot/event/webwalk/teleportExecute.ts
var SPELL_CAST_NAMES = {
  varrock: "Varrock",
  lumbridge: "Lumbridge",
  falador: "Falador",
  camelot: "Camelot",
  ardougne: "Ardougne",
  watchtower: "Watchtower",
  trollheim: "Trollheim"
};
var LAND_WAIT_MS = 8000;
var DIALOGUE_WAIT_MS = 4000;
function nearLanding(transport, before) {
  const t = reader.worldTile();
  if (!t) {
    return false;
  }
  if (transport.toTile) {
    const levelOk = transport.toLevel === undefined || t.level === transport.toLevel;
    return levelOk && Math.max(Math.abs(t.x - transport.toTile.x), Math.abs(t.z - transport.toTile.z)) <= 3;
  }
  if (!before) {
    return false;
  }
  return t.x !== before.x || t.z !== before.z || t.level !== before.level;
}
function findJewelleryItem(dest) {
  return Inventory.items().find((i2) => i2.name !== null && inventoryNameMatchesJewellery(i2.name, dest)) ?? null;
}
async function executeTeleportHop(transport, log) {
  const id = transport.teleportId ?? "";
  const dest = teleportById(id);
  const before = reader.worldTile();
  const spellName = SPELL_CAST_NAMES[id];
  if (spellName) {
    log(`casting ${spellName} teleport…`);
    if (!await Game.teleport(spellName)) {
      log(`${spellName} teleport cast failed`);
      return false;
    }
    const landed2 = await Execution.delayUntil(() => nearLanding(transport, before), LAND_WAIT_MS);
    if (landed2) {
      await Execution.delayTicks(2);
      log(`${spellName} teleport ok`);
      return true;
    }
    log(`${spellName} teleport did not land`);
    return false;
  }
  if (!dest || dest.family !== "jewellery") {
    log(`teleport hop ${id || transport.locName}: unknown id — repath`);
    return false;
  }
  const item = findJewelleryItem(dest);
  if (!item) {
    log(`jewellery tele ${id}: no matching inventory item`);
    return false;
  }
  const rubOp = item.actions().find((a) => /^rub$/i.test(a));
  if (!rubOp) {
    log(`jewellery tele ${id}: ${item.name} has no Rub (${item.actions().join(", ")})`);
    return false;
  }
  log(`rubbing ${item.name} for ${dest.label}…`);
  if (!await item.interact(rubOp)) {
    log(`rub failed on ${item.name}`);
    return false;
  }
  const choose = dest.dialogueChoose ?? [];
  if (choose.length > 0) {
    const gotDialog = await Execution.delayUntil(() => ChatDialog.options().length > 0, DIALOGUE_WAIT_MS);
    if (!gotDialog) {
      log(`jewellery tele ${id}: no dialog after Rub`);
      return false;
    }
    const pick = pickChoice(ChatDialog.options(), choose);
    if (!pick) {
      log(`jewellery tele ${id}: no matching option among [${ChatDialog.options().join(" | ")}] want ${choose.join("/")}`);
      return false;
    }
    await ChatDialog.chooseOption(pick);
  }
  const landed = await Execution.delayUntil(() => nearLanding(transport, before), LAND_WAIT_MS);
  if (landed) {
    await Execution.delayTicks(2);
    log(`jewellery tele ${id} ok`);
    return true;
  }
  log(`jewellery tele ${id} did not land`);
  return false;
}

// src/bot/event/webwalk/bankPlan.ts
var WITHDRAW_COST = BANK_WITHDRAW_COST;
function itemsRequiredByWaypoints(waypoints) {
  const need = {};
  const bump = (name, count) => {
    if (count <= 0) {
      return;
    }
    if (name.toLowerCase() === "coins") {
      need[name] = (need[name] ?? 0) + count;
      return;
    }
    need[name] = Math.max(need[name] ?? 0, count);
  };
  for (let i2 = 0;i2 < waypoints.length; i2++) {
    const wp = waypoints[i2];
    const t = wp.transport;
    if (!t) {
      continue;
    }
    if (t.teleportId) {
      const dest = SPELL_TELEPORTS.find((d) => d.teleportId === t.teleportId) ?? JEWELLERY_TELEPORTS.find((d) => d.teleportId === t.teleportId);
      if (dest?.requires?.items) {
        for (const it of dest.requires.items) {
          bump(it.name, it.count);
        }
      }
      continue;
    }
    const prev = waypoints[i2 - 1] ?? wp;
    const sc = specialCrossingForTransport(t, { x: prev.x, z: prev.z, level: prev.level }, { x: wp.x, z: wp.z, level: wp.level });
    if (sc?.requires) {
      bump(sc.requires.item, sc.requires.count);
    }
    if (isSlashWebTransport(t.locName, t.action)) {
      bump(WEB_SLASH_KNIFE_NAME, 1);
    }
  }
  return need;
}
function missingItemsForPath(waypoints, state) {
  const ws = worldStateFromData(state);
  const need = itemsRequiredByWaypoints(waypoints);
  const missing = [];
  for (const [name, count] of Object.entries(need)) {
    if (name === WEB_SLASH_KNIFE_NAME && state.canSlashWeb === true) {
      continue;
    }
    const have = ws.itemCount(name);
    if (have < count) {
      missing.push({ name, count: count - have });
    }
  }
  return missing;
}
function planBankLeg(input) {
  if (input.directHasTeleport) {
    return { action: "skip", reason: "direct path already uses teleport" };
  }
  if (input.missing.length === 0) {
    return { action: "skip", reason: "no missing items on virtual path" };
  }
  const via = input.toBankCost + WITHDRAW_COST + input.bankToDestCost;
  if (via >= input.directCost) {
    return {
      action: "skip",
      reason: `bank route cost ${via} >= direct ${input.directCost}`
    };
  }
  return { action: "bank", missing: input.missing, estimatedCost: via };
}
function pathHasTeleport(waypoints) {
  return waypoints.some((w) => w.transport?.teleportId !== undefined || w.transport?.kind === "teleport");
}

// src/bot/event/webwalk/virtualState.ts
function virtualizeWithItems(state, add) {
  const items = { ...state.items };
  for (const [name, count] of Object.entries(add)) {
    if (count <= 0) {
      continue;
    }
    const cur = lookupLoose(items, name);
    items[name] = cur + count;
    for (const k of Object.keys(items)) {
      if (k !== name && namesMatch(k, name)) {
        items[k] = items[name];
      }
    }
  }
  const worn = state.worn ? { ...state.worn } : {};
  return {
    members: state.members,
    skills: { ...state.skills },
    quests: { ...state.quests },
    items,
    worn,
    freeSlots: state.freeSlots,
    entranaRestrictedGear: state.entranaRestrictedGear === true,
    wildernessLevel: state.wildernessLevel,
    canSlashWeb: state.canSlashWeb === true || recordsHaveSlashTool(items, worn)
  };
}
function namesMatch(a, b) {
  const na = a.toLowerCase().replace(/\s+/g, "");
  const nb = b.toLowerCase().replace(/\s+/g, "");
  return na === nb;
}
function lookupLoose(items, name) {
  if (items[name] !== undefined) {
    return items[name];
  }
  const lower = name.toLowerCase();
  if (items[lower] !== undefined) {
    return items[lower];
  }
  const compact = lower.replace(/\s+/g, "");
  for (const [k, v] of Object.entries(items)) {
    if (k.toLowerCase() === lower || k.toLowerCase().replace(/\s+/g, "") === compact) {
      return v;
    }
  }
  return 0;
}

// src/bot/event/webwalk/gateItems.ts
function gateItemCandidates() {
  const out = { [WEB_SLASH_KNIFE_NAME]: 1 };
  for (const crossing of SPECIAL_CROSSINGS) {
    const req = crossing.requires;
    if (!req) {
      continue;
    }
    out[req.item] = Math.max(out[req.item] ?? 0, req.count);
  }
  return out;
}
async function explainUnreachable(probe, state) {
  const withKit = await probe(virtualizeWithItems(state, gateItemCandidates()));
  if (!withKit.ok) {
    return [];
  }
  return missingItemsForPath(withKit.waypoints, state);
}

// src/bot/event/webwalk/routeRecovery.ts
function findForwardRecoveryIndex(tiles, me, fromIdx, isClickable, opts) {
  if (tiles.length === 0) {
    return -1;
  }
  const corridor = opts?.corridor ?? 3;
  const window2 = opts?.window ?? 40;
  const limitIdx = Math.min(opts?.limitIdx ?? tiles.length - 1, tiles.length - 1);
  const hi = Math.min(fromIdx + window2, limitIdx);
  let bestClickable = -1;
  let bestOnCorridor = -1;
  for (let i2 = fromIdx + 1;i2 <= hi; i2++) {
    const t = tiles[i2];
    if (t.level !== me.level) {
      continue;
    }
    if (t.x === me.x && t.z === me.z) {
      continue;
    }
    if (chebyshev(me, t) <= corridor) {
      bestOnCorridor = i2;
    }
    if (isClickable(t)) {
      bestClickable = i2;
    }
  }
  if (bestClickable !== -1) {
    return bestClickable;
  }
  return bestOnCorridor;
}
