async function openedReady(log) {
  if (!Bank.isOpen()) {
    return false;
  }
  await Bank.waitReady(4000, log);
  return Bank.isOpen();
}
function locWithAction(name, op) {
  const wanted = op.toLowerCase();
  return Locs.query().name(name).where((loc) => loc.actions().some((action) => action.toLowerCase() === wanted)).nearest();
}
function bankStand(booth) {
  const me = reader.worldTile();
  const neighbours = [
    { x: booth.x + 1, z: booth.z, level: booth.level },
    { x: booth.x - 1, z: booth.z, level: booth.level },
    { x: booth.x, z: booth.z + 1, level: booth.level },
    { x: booth.x, z: booth.z - 1, level: booth.level }
  ];
  const reachable = neighbours.filter((t) => Reachability.canReach(t));
  if (reachable.length === 0) {
    return null;
  }
  if (!me) {
    return reachable[0];
  }
  const cheb = (t) => Math.max(Math.abs(t.x - me.x), Math.abs(t.z - me.z));
  return reachable.sort((a, b) => cheb(a) - cheb(b))[0];
}
function clickInvButton(items, name, opLabel) {
  const wanted = name.toLowerCase();
  return clickInvButtonMatching(items, (i2) => i2.name?.toLowerCase() === wanted, opLabel);
}
function clickInvButtonById(items, id, opLabel) {
  return clickInvButtonMatching(items, (i2) => i2.id === id, opLabel);
}
function clickInvButtonMatching(items, matches2, opLabel) {
  const item = items.find(matches2);
  if (!item) {
    return false;
  }
  const norm = (s) => s.toLowerCase().replace(/[\s-]+/g, " ").trim();
  const opWanted = norm(opLabel);
  for (let i2 = 0;i2 < item.ops.length; i2++) {
    const op = item.ops[i2];
    if (op !== null && norm(op) === opWanted) {
      return Input.invButton(item.id, item.slot, item.comId, i2 + 1);
    }
  }
  return false;
}
function bestOpIndex(ops) {
  for (let i2 = ops.length - 1;i2 >= 0; i2--) {
    if (ops[i2]) {
      return i2 + 1;
    }
  }
  return -1;
}

