function getUniversalGatherStep(name, snap, need) {
  const key = name.toLowerCase();
  const gatherer = UNIVERSAL_GATHERERS[key];
  if (gatherer) {
    return gatherer(snap, need);
  }
  return null;
}

// src/bot/api/ai/quests/ItemChecker.ts
function have(snapshot, name) {
  const wanted = name.toLowerCase();
  for (const [k, v] of snapshot.counts) {
    if (k.toLowerCase() === wanted) {
      return v;
    }
  }
  return 0;
}
function checkItems(record, snapshot) {
  return record.items.map((item) => {
    const present = have(snapshot, item.name);
    const canGather = UNIVERSAL_GATHERERS[item.name.toLowerCase()] !== undefined;
    if (item.kind === "mustHave" && !canGather) {
      const ok = present >= item.qty || snapshot.bankKnown === false;
      return { name: item.name, qty: item.qty, kind: item.kind, present, ok, willGather: false };
    }
    return { name: item.name, qty: item.qty, kind: item.kind, present, ok: true, willGather: present < item.qty };
  });
}

// src/bot/api/ai/quests/RequirementChecker.ts
function skillLabel(skill) {
  return skill.length === 0 ? skill : skill[0].toUpperCase() + skill.slice(1);
}
function checkRequirements(record, player) {
  const out = [];
  const req = record.requirements;
  if (req.minQuestPoints !== undefined) {
    const ok = player.questPoints >= req.minQuestPoints;
    out.push({ ok, reason: ok ? "" : `needs ${req.minQuestPoints} quest points (have ${player.questPoints})` });
  }
  for (const s of req.skills ?? []) {
    const have2 = player.skillLevels.get(s.skill) ?? 0;
    const ok = have2 >= s.level;
    out.push({ ok, reason: ok ? "" : `needs ${skillLabel(s.skill)} ${s.level} (have ${have2})` });
  }
  for (const q of req.quests ?? []) {
    const ok = player.completedQuests.has(q);
    out.push({ ok, reason: ok ? "" : `prerequisite quest not complete: ${q}` });
  }
  return out;
}

// src/bot/api/ai/quests/EligibilityEvaluator.ts
function evaluate(record, player, snapshot, journalStatus) {
  if (journalStatus === "complete") {
    return { id: record.id, name: record.name, status: "DONE", reasons: [] };
  }
  const reasons = [];
  for (const r of checkRequirements(record, player)) {
    if (!r.ok) {
      reasons.push(r.reason);
    }
  }
  if (journalStatus !== "inProgress") {
    for (const it of checkItems(record, snapshot)) {
      if (!it.ok) {
        reasons.push(`missing item: ${it.name} x${it.qty} (have ${it.present})`);
      }
    }
  }
  return {
    id: record.id,
    name: record.name,
    status: reasons.length === 0 ? "READY" : "BLOCKED",
    reasons
  };
}

