// src/bot/api/walking/Reach.ts
var REACH_BFS_STEPS = 400;
var PROBE_RADIUS = 10;
async function closeIn(near, radius, log) {
  const ok = await Traversal.walkResilient(near, { radius, attempts: 4, timeoutMs: 90000, log });
  if (!ok && WalkExecutor.lastOutcome === "unreachable") {
    log(`reach: hint (${near.x},${near.z},${near.level}) is unreachable`);
    return "unreachable";
  }
  return "retry";
}
var LOC_SCENE_MS = 3000;
async function sceneSettled(find, near, within) {
  const here = reader.worldTile();
  if (!here || here.level !== near.level || chebyshev(here, near) > within) {
    return false;
  }
  return Execution.delayUntil(() => find() !== null, LOC_SCENE_MS);
}
var REACH_DOOR_ATTEMPTS = 8;
function doorApproachable(doorTile) {
  for (let dx = -1;dx <= 1; dx++) {
    for (let dz = -1;dz <= 1; dz++) {
      if (Reachability.canReach({ x: doorTile.x + dx, z: doorTile.z + dz, level: doorTile.level }, { maxSteps: REACH_BFS_STEPS })) {
        return true;
      }
    }
  }
  return false;
}
async function openBlockingDoor(toward, log) {
  const here = reader.worldTile();
  if (!here) {
    return false;
  }
  const door = Locs.query().where((l) => isOpenableBarrier(l.name, l.actions())).where((l) => l.distance() <= 6 && towardDest(l.tile(), here, toward) && doorApproachable(l.tile())).nearest();
  if (!door) {
    return false;
  }
  const t = door.tile();
  if (chebyshev(here, t) > 1) {
    await Traversal.walkResilient(t, { radius: 1, attempts: 3, timeoutMs: 30000, log });
  }
  const shut = Locs.query().where((l) => l.tile().x === t.x && l.tile().z === t.z && isOpenableBarrier(l.name, l.actions())).nearest();
  if (!shut) {
    return true;
  }
  const op = openOp(shut.actions());
  if (!op) {
    return false;
  }
  log(`reach: opening blocking '${shut.name}' at (${t.x},${t.z})`);
  const mark = GameMessages.mark();
  if (!await shut.interact(op)) {
    return false;
  }
  return Execution.delayUntil(() => {
    if (chatShowsQuestLock(mark)) {
      return false;
    }
    const still = Locs.query().where((l) => l.tile().x === t.x && l.tile().z === t.z && isOpenableBarrier(l.name, l.actions())).nearest();
    return still === null;
  }, 5000);
}
async function reachThroughDoors(attempt, expect, expectMs, targetTile, what, log, retryAfterTimeout = true, probeUnreachable = false, refused) {
  for (let i2 = 0;i2 < REACH_DOOR_ATTEMPTS; i2++) {
    if (probeUnreachable && !expect()) {
      const blocked = targetTile();
      const here = reader.worldTile();
      if (blocked && here && blocked.level === here.level && chebyshev(here, blocked) <= PROBE_RADIUS && !Reachability.canReach(blocked, { maxSteps: REACH_BFS_STEPS, adjacentOk: true }) && await openBlockingDoor(blocked, log)) {
        continue;
      }
    }
    const mark = GameMessages.mark();
    const dispatched = await attempt();
    if (dispatched) {
      await Execution.delayUntil(() => expect() || GameMessages.sawSince(mark, CANT_REACH) || refused !== undefined && GameMessages.sawSince(mark, refused), expectMs);
      if (expect()) {
        return "done";
      }
      if (refused !== undefined && GameMessages.sawSince(mark, refused)) {
        log(`reach: '${what}' refused the op — not retrying`);
        return "retry";
      }
      if (GameMessages.sawSince(mark, CANT_REACH)) {
        const toward = targetTile();
        if (!toward || !await openBlockingDoor(toward, log)) {
          log(`reach: '${what}' — server can't reach it and no openable door in front (unreachable)`);
          return "unreachable";
        }
        continue;
      }
    }
    if (!retryAfterTimeout) {
      if (!dispatched) {
        await Execution.delayTicks(1);
      }
      return "retry";
    }
    await Execution.delayTicks(1);
  }
  return "retry";
}
var Reach = {
  async entityOp(opts) {
    const log = opts.log ?? (() => {});
    return reachThroughDoors(async () => {
      if (opts.expect()) {
        return true;
      }
      const entity = opts.find();
      return entity ? await entity.interact(opts.op) : false;
    }, opts.expect, opts.expectMs ?? 5000, () => opts.find()?.tile() ?? null, opts.what ?? opts.op, log, false, opts.openWhenUnreachable ?? false);
  },
  async locOp(opts) {
    const log = opts.log ?? (() => {});
    const find = () => Locs.query().name(opts.name).action(opts.op).within(opts.within ?? 10).where((l) => opts.id === undefined || l.id === opts.id).nearest();
    if (!find() && !await sceneSettled(find, opts.near, opts.within ?? 10)) {
      return closeIn(opts.near, 2, log);
    }
    const arrived = await Traversal.walkResilient(opts.near, { radius: 1, attempts: 4, timeoutMs: 90000, log });
    if (!arrived && WalkExecutor.lastOutcome === "unreachable") {
      log(`reach: stand (${opts.near.x},${opts.near.z},${opts.near.level}) unreachable`);
      return "unreachable";
    }
    return reachThroughDoors(async () => {
      const loc = find();
      return loc ? await loc.interact(opts.op) : false;
    }, opts.expect, opts.expectMs ?? 12000, () => find()?.tile() ?? null, opts.name, log, true, false, opts.refused);
  },
  async npcDialog(opts) {
    const log = opts.log ?? (() => {});
    if (ChatDialog.isOpen()) {
      const cur = Npcs.query().name(opts.name).nearest();
      const me = reader.worldTile();
      if (cur && me && cur.tile().level === me.level && Math.max(Math.abs(cur.tile().x - me.x), Math.abs(cur.tile().z - me.z)) <= 1) {
        return "done";
      }
      return "retry";
    }
    const find = () => Npcs.query().name(opts.name).where((n) => talkOp(n.actions()) !== null).nearest();
    if (!find()) {
      return closeIn(opts.near, 3, log);
    }
    const arrived = await Traversal.walkResilient(opts.near, { radius: 1, attempts: 4, timeoutMs: 90000, log });
    if (!arrived && WalkExecutor.lastOutcome === "unreachable") {
      log(`reach: stand (${opts.near.x},${opts.near.z},${opts.near.level}) unreachable`);
      return "unreachable";
    }
    return reachThroughDoors(async () => {
      const npc = find();
      return npc ? await npc.interact(talkOp(npc.actions()) ?? "Talk-to") : false;
    }, () => ChatDialog.isOpen() || ChatDialog.canContinue(), opts.openMs ?? 15000, () => find()?.tile() ?? null, opts.name, log, true, true);
  }
};

// src/bot/api/ai/quests/exec/primitives.ts
function pickPreferred(options, prefer) {
  for (const p of prefer) {
    const hit = options.find((o) => o.toLowerCase().includes(p.toLowerCase()));
    if (hit) {
      return hit;
    }
  }
  return null;
}
function flattenLines(lines) {
  return lines.join(" ").replace(/@[a-z0-9]{3}@/gi, " ").replace(/[|\s]+/g, " ").trim().toLowerCase();
}
function pickByLine(lines, options, rules) {
  const said = flattenLines(lines);
  if (said.length === 0) {
    return null;
  }
  const hit = [...rules].sort((a, b) => b.whenLine.length - a.whenLine.length).find((rule) => said.includes(rule.whenLine.toLowerCase()));
  if (!hit) {
    return null;
  }
  return options.find((o) => o.toLowerCase().includes(hit.choose.toLowerCase())) ?? null;
}
function isUnderground(t) {
  return t.z >= 5000;
}
function needsHop(here, anchor) {
  return isUnderground(here) !== isUnderground(anchor);
}
async function hopLadder(hop, log) {
  const find = (op) => Locs.query().name(hop.locName).action(op).where((l) => l.tile().distanceTo(hop.stand) <= 3).nearest();
  let ladder = find(hop.op);
  if (!ladder && hop.open !== undefined) {
    const closed = find(hop.open);
    if (closed && await closed.interact(hop.open)) {
      await Execution.delayTicks(2);
      ladder = find(hop.op);
      if (!ladder) {
        await Execution.delayTicks(2);
        ladder = find(hop.op);
      }
    }
  }
  if (!ladder) {
    log(`no '${hop.locName}' offering '${hop.op}' near (${hop.stand.x},${hop.stand.z})`);
    return false;
  }
  if (!await ladder.interact(hop.op)) {
    return false;
  }
  return Execution.delayUntil(() => {
    const t = Game.tile();
    return t !== null && t.level === hop.arrive.level && hop.arrive.distanceTo(t) <= 5;
  }, 8000);
}
async function crossHops(here, dest, hops, log) {
  if (!needsHop(here, dest)) {
    return here;
  }
  const near = hops.filter((h) => isUnderground(h.stand) === isUnderground(here));
  const hop = near.sort((a, b) => a.stand.distanceTo(here) - b.stand.distanceTo(here))[0];
  if (!hop) {
    log(`no hop from (${here.x},${here.z}) toward z ${dest.z} — trying the baked graph`);
    return here;
  }
  if (hop.stand.distanceTo(here) > 2 && !await Traversal.walkResilient(hop.stand, { radius: 2, attempts: 3, log })) {
    return null;
  }
  if (!await hopLadder(hop, log)) {
    return null;
  }
  return Game.tile();
}
async function walkWithHops(dest, radius, hops, log) {
  const start = Game.tile();
  if (!start) {
    return false;
  }
  const here = await crossHops(start, dest, hops, log);
  if (!here) {
    return false;
  }
  if (here.level !== dest.level || dest.distanceTo(here) > radius) {
    return Traversal.walkResilient(dest, { radius, attempts: 3, log });
  }
  return true;
}
async function gotoNpc(stop, hops, log) {
  let here = Game.tile();
  if (!here) {
    return false;
  }
  const npcNear = () => {
    const n = Npcs.query().name(stop.npc).nearest();
    return n !== null && n.distance() <= stop.leash;
  };
  const hopped = await crossHops(here, stop.anchor, hops, log);
  if (!hopped) {
    return false;
  }
  here = hopped;
  let approachFailed = false;
  for (const wp of stop.approach ?? []) {
    if (wp.distanceTo(here) > 2) {
      if (!await Traversal.walkResilient(wp, { radius: 2, attempts: 2, timeoutMs: 45000, log })) {
        approachFailed = true;
        here = Game.tile() ?? here;
        break;
      }
      here = Game.tile() ?? here;
    }
  }
  if (!approachFailed && stop.anchor.distanceTo(here) > 1) {
    await Traversal.walkResilient(stop.anchor, { radius: 1, attempts: 2, timeoutMs: 45000, log });
    here = Game.tile() ?? here;
  }
  if (isUnderground(here) && isUnderground(stop.anchor) && stop.anchor.distanceTo(here) > 2 && stop.anchor.distanceTo(here) <= 20) {
    const back = hops.find((h) => isUnderground(h.stand) === isUnderground(here));
    if (back) {
      log(`trapped landing at (${here.x},${here.z}) — could not reach anchor, climbing back to re-roll`);
      if (back.stand.distanceTo(here) > 1) {
        await Traversal.walkResilient(back.stand, { radius: 1, attempts: 3, log });
      }
      await hopLadder(back, log);
    }
    return false;
  }
  if (approachFailed) {
    return false;
  }
  return npcNear();
}
var DIALOG_GAP_MS = 1500;
async function driveDialog(prefer, log, gapMs = DIALOG_GAP_MS) {
  for (let i2 = 0;i2 < 120; i2++) {
    if (EventSignal.pending()) {
      return false;
    }
    if (!ChatDialog.isOpen() && !ChatDialog.canContinue()) {
      if (!await Execution.delayUntil(() => ChatDialog.isOpen() || ChatDialog.canContinue(), gapMs)) {
        break;
      }
    }
    if (ChatDialog.canContinue()) {
      await ChatDialog.continue();
      await Execution.delayTicks(1);
      continue;
    }
    const opts = ChatDialog.options();
    if (opts.length > 0) {
      const pick = pickPreferred(opts, prefer);
      if (!pick) {
        log(`WARN: no preferred option in [${opts.join(" | ")}] — taking the last`);
      }
      await ChatDialog.chooseOption(pick ?? opts[opts.length - 1]);
      await Execution.delayTicks(2);
      continue;
    }
    await Execution.delayTicks(1);
  }
  return !ChatDialog.isOpen();
}
var DIALOGUE_OPEN_MS = 8000;
async function openDialogue(npcName, log) {
  const dialogReady = () => ChatDialog.isOpen() || ChatDialog.canContinue();
  if (dialogReady()) {
    return true;
  }
  for (let attempt = 0;attempt < 2; attempt++) {
    const find = () => Npcs.query().name(npcName).where((n) => talkOp(n.actions()) !== null).nearest();
    const npc = find();
    if (!npc) {
      log(`no '${npcName}' nearby to talk to`);
      return false;
    }
    const status = await Reach.entityOp({
      find,
      op: talkOp(npc.actions()),
      expect: dialogReady,
      openWhenUnreachable: true,
      expectMs: DIALOGUE_OPEN_MS,
      what: npcName,
      log
    });
    if (status === "done") {
      return true;
    }
    if (status === "unreachable") {
      break;
    }
    await Execution.delayTicks(2);
  }
  log(`'${npcName}' never opened a dialogue`);
  return false;
}
async function talkThrough(npcName, prefer, log, gapMs) {
  if (!await openDialogue(npcName, log)) {
    return false;
  }
  return driveDialog(prefer, log, gapMs);
}
function talkStrict(npcName, prefer, log) {
  return talkChoosingBy(npcName, [], prefer, log);
}
async function talkChoosingBy(npcName, rules, prefer, log) {
  if (!await openDialogue(npcName, log)) {
    return false;
  }
  let spoken = [];
  for (let i2 = 0;i2 < 120; i2++) {
    if (EventSignal.pending()) {
      return false;
    }
    const opts = ChatDialog.options();
    if (opts.length === 0 && ChatDialog.isOpen()) {
      const texts = ChatDialog.texts();
      if (texts.length > 0) {
        spoken = texts;
      }
    }
    if (ChatDialog.canContinue()) {
      await ChatDialog.continue();
      await Execution.delayTicks(1);
      continue;
    }
    if (opts.length > 0) {
      const pick = pickByLine(spoken, opts, rules) ?? pickPreferred(opts, prefer);
      if (!pick) {
        log(`no rule or preference matched [${opts.join(" | ")}] after "${spoken.join(" ")}"`);
        return false;
      }
      await ChatDialog.chooseOption(pick);
      await Execution.delayTicks(2);
      continue;
    }
    if (!ChatDialog.isOpen()) {
      break;
    }
    await Execution.delayTicks(1);
  }
  return !ChatDialog.isOpen();
}

