    return ROMEO_JULIET_STAGE.SPOKEN_TO_FATHER;
  if (text.includes("i should find father lawrence"))
    return ROMEO_JULIET_STAGE.PASSED_MESSAGE;
  if (text.includes("i should take the message") && text.includes("to romeo")) {
    return ROMEO_JULIET_STAGE.SPOKEN_TO_JULIET;
  }
  if (text.includes("i should go and speak to juliet"))
    return ROMEO_JULIET_STAGE.SPOKEN_TO_ROMEO;
  if (text.includes("i can start this quest by talking to romeo"))
    return ROMEO_JULIET_STAGE.NOT_STARTED;
