// src/bot/api/ai/quests/defs/princeali/supplies.ts
var PURSE_FLOOR = 150;
var PURSE_TOP = 1000;
var PICKAXE_IDS2 = [1265, 1267, 1269, 1271, 1273, 1275];
function held4(snap, id) {
  return snap.invIds?.get(id) ?? 0;
}
function banked2(snap, id) {
  return snap.bankIds?.get(id) ?? 0;
}
function owned(snap, id) {
  return held4(snap, id) + banked2(snap, id);
}
function heldItem(id) {
  return Inventory.items().find((item) => item.id === id) ?? null;
}
function hasAnyPickaxe(snap) {
  return PICKAXE_IDS2.some((id) => held4(snap, id) > 0 || (snap.wornIds?.has(id) ?? false));
}
function scanBank2() {
  return { kind: "scanBank" };
}
function withdrawFrom(items) {
  return { kind: "withdraw", items };
}
function fromBank(snap, item, qty = 1) {
  const short = qty - held4(snap, item.id);
  if (short <= 0) {
    return null;
  }
  if (!snap.bankKnown) {
    return scanBank2();
  }
  const inBank = banked2(snap, item.id);
  return inBank > 0 ? withdrawFrom([{ name: item.name, id: item.id, qty: Math.min(short, inBank) }]) : null;
}
function buyItem(snap, item, qty, shop, unitGp) {
  const short = qty - held4(snap, item.id);
  if (short <= 0) {
    return null;
  }
  return fromBank(snap, item, qty) ?? { kind: "buy", item: item.name, qty: short, shop, estGp: short * unitGp };
}
function grabItem(snap, item, anchor) {
  if (held4(snap, item.id) > 0) {
    return null;
  }
  return fromBank(snap, item, 1) ?? { kind: "grabGround", item: item.name, anchor, waitIfMissing: true };
}
function sourceCoins(snap, floor, top) {
  const purse = held4(snap, PA_ITEM.COINS.id);
  if (purse >= floor) {
    return null;
  }
  if (!snap.bankKnown) {
    return scanBank2();
  }
  const available = banked2(snap, PA_ITEM.COINS.id);
  if (available <= 0) {
    return { kind: "wait", reason: "no coins in the bank for shops, dialogue purchases and the toll gate" };
  }
  return withdrawFrom([{ name: PA_ITEM.COINS.name, id: PA_ITEM.COINS.id, qty: Math.min(top - purse, available) }]);
}

// src/bot/api/ai/quests/defs/princeali/disguise.ts
var WOOL_SITES = {
  pen: PA_TILE.SHEEP_PEN,
  wheelStand: PA_TILE.SPIN_STAND,
  shearsSpawn: PA_TILE.SHEARS_SPAWN,
  spinLabel: "spin wool at Lumbridge"
};
var BALLS_FOR_WIG = 3;
var ONIONS_FOR_DYE = 2;
var TINDERBOX_GP = 10;
var SHEARS_GP = 10;
var SKIRT_GP = 20;
var REDBERRIES_GP = 20;
var FLOUR_GP = 30;
function haveWig(snap) {
  return owned(snap, PA_ITEM.BLOND_WIG.id) > 0 || owned(snap, PA_ITEM.PLAIN_WIG.id) > 0;
}
function haveDye(snap) {
  return owned(snap, PA_ITEM.BLOND_WIG.id) > 0 || owned(snap, PA_ITEM.YELLOW_DYE.id) > 0;
}
function havePaste(snap) {
  return owned(snap, PA_ITEM.PASTE.id) > 0;
}
function disguiseComplete(snap) {
  return held4(snap, PA_ITEM.BLOND_WIG.id) > 0 && held4(snap, PA_ITEM.PINK_SKIRT.id) > 0 && held4(snap, PA_ITEM.PASTE.id) > 0;
}
function sourceTinderbox(snap) {
  if (havePaste(snap) || owned(snap, PA_ITEM.ASHES.id) > 0) {
    return null;
  }
  return buyItem(snap, PA_ITEM.TINDERBOX, 1, PA_SHOP.LUMBRIDGE, TINDERBOX_GP);
}
function sourceShears(snap) {
  if (haveWig(snap) || owned(snap, PA_ITEM.BALL_OF_WOOL.id) >= BALLS_FOR_WIG) {
    return null;
  }
  return buyItem(snap, PA_ITEM.SHEARS, 1, PA_SHOP.LUMBRIDGE, SHEARS_GP);
}
function sourceOnions(snap) {
  if (haveDye(snap) || held4(snap, PA_ITEM.ONION.id) >= ONIONS_FOR_DYE) {
    return null;
  }
  return fromBank(snap, PA_ITEM.ONION, ONIONS_FOR_DYE) ?? { kind: "pickLoc", loc: PA_LOC.ONION, op: "Pick", item: PA_ITEM.ONION.name, anchor: PA_TILE.ONION_PATCH };
}
function sourceWool(snap) {
  if (haveWig(snap) || held4(snap, PA_ITEM.BALL_OF_WOOL.id) >= BALLS_FOR_WIG) {
    return null;
  }
  const banked3 = fromBank(snap, PA_ITEM.BALL_OF_WOOL, BALLS_FOR_WIG);
  if (banked3) {
    return banked3;
  }
  const shears = held4(snap, PA_ITEM.SHEARS.id) > 0 ? [["shears", 1]] : [];
  const woolSnap = {
    ...snap,
    inv: new Map([["wool", held4(snap, PA_ITEM.WOOL.id)], ...shears])
  };
  return gatherWool(woolSnap, BALLS_FOR_WIG - held4(snap, PA_ITEM.BALL_OF_WOOL.id), WOOL_SITES);
}
function sourcePinkSkirt(snap) {
  return buyItem(snap, PA_ITEM.PINK_SKIRT, 1, PA_SHOP.THESSALIA, SKIRT_GP);
}
function sourcePasteGoods(snap) {
  if (havePaste(snap)) {
    return null;
  }
  return buyItem(snap, PA_ITEM.REDBERRIES, 1, PA_SHOP.WYDIN, REDBERRIES_GP) ?? buyItem(snap, PA_ITEM.POT_OF_FLOUR, 1, PA_SHOP.WYDIN, FLOUR_GP);
}
function makeAshes(snap) {
  if (havePaste(snap) || owned(snap, PA_ITEM.ASHES.id) > 0 || held4(snap, PA_ITEM.TINDERBOX.id) === 0) {
    return null;
  }
  return grabItem(snap, PA_ITEM.LOGS, PA_TILE.LOGS_SPAWN) ?? { kind: "custom", name: "burn the logs for ashes", run: burnLogs };
}
function makeBlondWig(snap) {
  if (owned(snap, PA_ITEM.BLOND_WIG.id) > 0) {
    return fromBank(snap, PA_ITEM.BLOND_WIG, 1);
  }
  if (held4(snap, PA_ITEM.YELLOW_DYE.id) === 0) {
    if (held4(snap, PA_ITEM.ONION.id) < ONIONS_FOR_DYE) {
      return null;
    }
    return { kind: "custom", name: "have Aggie make yellow dye", run: makeYellowDye };
  }
  if (held4(snap, PA_ITEM.PLAIN_WIG.id) === 0) {
    if (held4(snap, PA_ITEM.BALL_OF_WOOL.id) < BALLS_FOR_WIG) {
      return null;
    }
    return { kind: "talk", stop: NED_WIG };
  }
  return { kind: "custom", name: "dye the wig blond", run: dyeWig };
}
function makePaste(snap) {
  if (havePaste(snap)) {
    return fromBank(snap, PA_ITEM.PASTE, 1);
  }
  const missing = [
    held4(snap, PA_ITEM.REDBERRIES.id) === 0 ? PA_ITEM.REDBERRIES.name : null,
    held4(snap, PA_ITEM.POT_OF_FLOUR.id) === 0 ? PA_ITEM.POT_OF_FLOUR.name : null,
    held4(snap, PA_ITEM.ASHES.id) === 0 ? PA_ITEM.ASHES.name : null,
    held4(snap, PA_ITEM.JUG_OF_WATER.id) === 0 ? PA_ITEM.JUG_OF_WATER.name : null
  ];
  const absent = missing.filter((name) => name !== null);
  if (absent.length > 0) {
    return { kind: "wait", reason: `paste needs ${absent.join(", ")}` };
  }
  return { kind: "talk", stop: AGGIE_PASTE };
}
async function useHeldOnNpc(itemId, npcName, near, expect, log) {
  if (expect()) {
    return true;
  }
  if (!await Traversal.walkResilient(near, { radius: 3, attempts: 3, timeoutMs: 120000, log })) {
    return false;
  }
  await settleScene();
  const npc = Npcs.query().name(npcName).within(10).nearest();
  const item = heldItem(itemId);
  if (!npc || !item) {
    log(`useHeldOnNpc: no '${npcName}' or no item ${itemId} in the pack`);
    return false;
  }
  if (!await item.useOn(npc)) {
    return false;
  }
  return driveUntil(expect, [], log);
}
async function burnLogs(log) {
  if (heldItem(PA_ITEM.ASHES.id)) {
    return true;
  }
  const tinder = heldItem(PA_ITEM.TINDERBOX.id);
  const logs = heldItem(PA_ITEM.LOGS.id);
  if (!tinder || !logs) {
    log("burnLogs: no tinderbox or no logs");
    return false;
  }
  if (Bank.isOpen()) {
    await Bank.close();
  }
  log(`burnLogs: lighting outside near ${PA_TILE.LOGS_SPAWN.x},${PA_TILE.LOGS_SPAWN.z}`);
  if (!await Traversal.walkResilient(PA_TILE.LOGS_SPAWN, { radius: 2, attempts: 3, timeoutMs: 90000, log })) {
    log("burnLogs: could not reach an outdoor fire tile");
    return false;
  }
  await settleScene();
  if (!await tinder.useOn(logs)) {
    return false;
  }
  const ashesNear = () => GroundItems.query().name(PA_ITEM.ASHES.name).within(3).nearest() !== null;
  if (!await Execution.delayUntil(ashesNear, 150000)) {
    log("burnLogs: the fire never left any ashes");
    return false;
  }
  const ash = GroundItems.query().name(PA_ITEM.ASHES.name).within(3).nearest();
  if (!ash || !await ash.interact("Take")) {
    return false;
  }
  return Execution.delayUntil(() => heldItem(PA_ITEM.ASHES.id) !== null, 5000);
}
function makeYellowDye(log) {
  return useHeldOnNpc(PA_ITEM.ONION.id, PA_NPC.AGGIE, PA_TILE.AGGIE, () => heldItem(PA_ITEM.YELLOW_DYE.id) !== null, log);
}
async function dyeWig(log) {
  if (heldItem(PA_ITEM.BLOND_WIG.id)) {
    return true;
  }
  const dye = heldItem(PA_ITEM.YELLOW_DYE.id);
  const wig = heldItem(PA_ITEM.PLAIN_WIG.id);
  if (!dye || !wig) {
    log("dyeWig: no yellow dye or no plain wig");
    return false;
  }
  if (!await dye.useOn(wig)) {
    return false;
  }
  return Execution.delayUntil(() => heldItem(PA_ITEM.BLOND_WIG.id) !== null, 8000);
}

// src/bot/api/ai/quests/defs/princeali/journal.ts
var PRINCE_QUEST = "Prince Ali Rescue";
var PRINCE_STAGE = {
  NOT_STARTED: 0,
  STARTED: 10,
  SPOKEN_OSMAN: 20,
  PREP_FINISHED: 30,
  GUARD_DRUNK: 40,
  TIED_KELI: 50,
  SAVED: 100,
  COMPLETE: 110
};
function normalize3(lines) {
  return (typeof lines === "string" ? lines : lines.join(" ")).replace(/@[a-z0-9]{3}@/gi, " ").replace(/[|\s]+/g, " ").trim().toLowerCase();
}
var STAGE_LINES = [
  ["quest complete!", PRINCE_STAGE.COMPLETE],
  ["i then used a wig, a skirt and some skin paste", PRINCE_STAGE.SAVED],
  ["i used my rope to tie up lady", PRINCE_STAGE.TIED_KELI],
  ["i also had to prevent the guard from seeing what i was up", PRINCE_STAGE.GUARD_DRUNK],
  ["i need to deal with the", PRINCE_STAGE.PREP_FINISHED],
  ["for advice", PRINCE_STAGE.SPOKEN_OSMAN],
  ["i should go and speak to", PRINCE_STAGE.STARTED],
  ["i can start this quest by speaking to", PRINCE_STAGE.NOT_STARTED]
];
function parsePrinceJournal(lines) {
  const text = normalize3(lines);
  if (text.length === 0) {
    return;
  }
  for (const [needle, stage] of STAGE_LINES) {
    if (text.includes(needle)) {
      return { stage, flags: new Set };
    }
  }
  return;
}
async function readPrinceProgress() {
  const status = Quests.status(PRINCE_QUEST);
  if (status === "complete") {
    return { stage: PRINCE_STAGE.COMPLETE, flags: new Set };
  }
  if (status === "notStarted") {
    return { stage: PRINCE_STAGE.NOT_STARTED, flags: new Set };
  }
  if (status !== "inProgress") {
    return;
  }
  for (let attempt = 0;attempt < 3; attempt++) {
    await closeMainModal();
    const progress = parsePrinceJournal(await Quests.journal(PRINCE_QUEST));
    await closeMainModal();
    if (progress) {
      return progress;
    }
    await Execution.delayTicks(1);
  }
  return;
}
async function closeMainModal() {
  if (reader.modals().main === -1) {
    return;
  }
  actions.closeModal();
  await Execution.delayUntil(() => reader.modals().main === -1, 2000);
}

