  await settleScene();
  if (findKeli()) {
    log("unlockCell: Lady Keli is still in the house");
    return false;
  }
  const key = heldItem(PA_ITEM.PRINCE_KEY.id);
  const door = Locs.query().name(PA_LOC.PRISON_DOOR).within(4).nearest();
