var BAR_GP = 40;
var WATER_GP = 20;
function haveKey(snap) {
  return held4(snap, PA_ITEM.PRINCE_KEY.id) > 0;
}
function keyDone(snap) {
  return owned(snap, PA_ITEM.PRINCE_KEY.id) > 0;
}
