  if (haveKey(snap)) {
    return null;
  }
  if (banked2(snap, PA_ITEM.PRINCE_KEY.id) > 0) {
    return withdrawFrom([{ name: PA_ITEM.PRINCE_KEY.name, id: PA_ITEM.PRINCE_KEY.id, qty: 1 }]);
  }
  if (keyIssued(snap)) {
    return { kind: "custom", name: "ask Leela to replace the lost key", run: collectFromLeela };
  }
  if (held4(snap, PA_ITEM.KEY_PRINT.id) === 0 || held4(snap, PA_ITEM.BRONZE_BAR.id) === 0) {
    return null;
  }
