// src/bot/api/ai/quests/defs/princeali/index.ts
var PREP = [
  sourceBronzeBar,
  sourceWater,
  sourceTinderbox,
  sourceShears,
  sourceOnions,
  sourceWool,
  sourcePinkSkirt,
  sourcePickaxe,
  sourceClay,
  sourcePasteGoods,
  sourceBeers,
  makeAshes,
  makeBlondWig,
  makePaste,
  sourceRopes,
  makeSoftClay,
  takeKeyPrint,
  collectKey
];
function prepLeg(snap) {
  for (const leg of PREP) {
    const step = leg(snap);
    if (step) {
      return step;
    }
  }
  return null;
}
async function leelaHandover(log) {
  if (!await gotoNpc(LEELA_STOP, [], log)) {
    return false;
  }
  return talkStrict(LEELA_STOP.npc, LEELA_STOP.prefer, log);
}
function decide11(snap) {
  if (snap.journal === "unknown") {
    return { kind: "wait", reason: "quest journal not loaded" };
  }
  if (snap.journal === "complete" || (snap.stage ?? -1) >= PRINCE_STAGE.COMPLETE) {
    return { kind: "done" };
  }
  const stage = snap.stage;
  if (stage === undefined) {
    return { kind: "wait", reason: "Prince Ali Rescue journal stage unavailable" };
  }
  const kitInHand = stage >= PRINCE_STAGE.GUARD_DRUNK && jailbreakKitReady(snap);
  if (!snap.bankKnown && !kitInHand) {
    return scanBank2();
  }
  if (stage < PRINCE_STAGE.SAVED && !kitInHand) {
    const purse = sourceCoins(snap, PURSE_FLOOR, PURSE_TOP);
    if (purse) {
      return purse;
    }
  }
  switch (stage) {
    case PRINCE_STAGE.NOT_STARTED:
      return { kind: "talk", stop: HASSAN_START };
    case PRINCE_STAGE.STARTED:
      return { kind: "talk", stop: OSMAN_BRIEF };
    case PRINCE_STAGE.SPOKEN_OSMAN: {
      const prep = prepLeg(snap);
      if (prep) {
        return prep;
      }
      if (!haveKey(snap) || !disguiseComplete(snap)) {
        return { kind: "wait", reason: "every prep leg is satisfied but the disguise or key is not in the pack" };
      }
      return { kind: "custom", name: "show Leela the disguise and collect the key", run: leelaHandover };
    }
    case PRINCE_STAGE.PREP_FINISHED:
    case PRINCE_STAGE.GUARD_DRUNK:
    case PRINCE_STAGE.TIED_KELI:
      if (kitInHand) {
        return decideJailbreak(snap);
      }
      return prepLeg(snap) ?? decideJailbreak(snap);
    case PRINCE_STAGE.SAVED:
      return { kind: "talk", stop: HASSAN_REWARD };
    default:
      return { kind: "wait", reason: `Prince Ali Rescue stage ${stage} is not implemented` };
  }
}
function stageName(stage) {
  switch (stage) {
    case PRINCE_STAGE.NOT_STARTED:
      return "not started, speak to Hassan in Al-Kharid Palace";
    case PRINCE_STAGE.STARTED:
      return "Hassan sent us to Osman";
    case PRINCE_STAGE.SPOKEN_OSMAN:
      return "Osman briefed, gather the disguise and Bronze key";
    case PRINCE_STAGE.PREP_FINISHED:
      return "prep finished, get Joe drunk";
    case PRINCE_STAGE.GUARD_DRUNK:
      return "Joe is drunk, tie Lady Keli";
    case PRINCE_STAGE.TIED_KELI:
      return "Keli is tied, unlock the cell and free Prince Ali";
    case PRINCE_STAGE.SAVED:
      return "Prince Ali is free, return to Hassan";
    case PRINCE_STAGE.COMPLETE:
      return "Prince Ali Rescue complete";
    default:
      return `stage ${stage}`;
  }
}
var princeali = {
  record: QUESTS.find((record) => record.id === "prince"),
  bank: PA_TILE.DRAYNOR_BANK,
  ownsInventory: true,
  readProgress: readPrinceProgress,
  stageName,
  decide: decide11
};

