// src/bot/api/ai/quests/exec/legs.ts
var CLIMB_MS = 12000;
var WALK_MS = 120000;
async function openContainer(name, shutId, openId, stand, log) {
  const open2 = () => Locs.query().within(6).where((l) => l.id === openId).nearest();
  for (let attempt = 0;attempt < 3; attempt++) {
    if (open2()) {
      return true;
    }
    await promptLoc({
      name,
      op: "Open",
      near: stand,
      id: shutId,
      within: 6,
      expect: () => open2() !== null
    }, log);
    await settleScene();
  }
  if (open2()) {
    return true;
  }
  log(`the shut ${name.toLowerCase()} (${shutId}) never became ${openId}`);
  return false;
}
async function climb(locId, op, stand, arrive, log) {
  const here2 = Game.tile();
  if (here2 && here2.level === arrive.level) {
    return true;
  }
  if (!await Traversal.walkResilient(stand, { radius: 1, attempts: 3, timeoutMs: WALK_MS, log })) {
    return false;
  }
  const loc = Locs.query().action(op).within(4).where((l) => l.id === locId).nearest();
  if (!loc) {
    log(`no loc ${locId} offering '${op}' near (${stand.x},${stand.z})`);
    return false;
  }
  if (!await loc.interact(op)) {
    log(`loc ${locId} refused '${op}'`);
    return false;
  }
  await Execution.delayUntil(() => {
    const t = Game.tile();
    return t !== null && t.level === arrive.level;
  }, CLIMB_MS);
  await settleScene();
  if (Game.tile()?.level === arrive.level) {
    return true;
  }
  log(`'${op}' on loc ${locId} never reached level ${arrive.level}`);
  return false;
}
