  if (Inventory.countById(SOA_ID.SHIELD_BLACKARM) === 0) {
    log(bare ? "the cupboard is bare — a half is already held or banked, or the quest is complete" : "the cupboard search landed nothing");
    await leaveBlackArmUpper(log);
    return false;
  }
