function hashName(name) {
  let hash = 2166136261;
  const norm = name.replace(/[^a-z0-9]/gi, "").toLowerCase();
  for (let i2 = 0;i2 < norm.length; i2++) {
    hash ^= norm.charCodeAt(i2);
    hash = Math.imul(hash, 16777619) >>> 0;
  }
  return hash >>> 0;
}
function resolveGang(setting, playerName) {
  if (setting !== "random") {
    return setting;
  }
  if (!playerName) {
    return "phoenix";
  }
  return (hashName(playerName) & 1) === 0 ? "phoenix" : "blackarm";
}

