// src/bot/api/trade/PartnerTrade.ts
var DEFAULT_TRADE_RANGE = 2;
function namesMatch2(a, b) {
  return a.trim().toLowerCase() === b.trim().toLowerCase();
}

// src/bot/api/trade/PartnerHandoff.ts
var MEET_MS = 90000;
var SCREEN_MS = 8000;
var HANDOFF_MS = 120000;
var OPEN_REQUEST_EVERY_MS = 3000;
function decideOpenTrade(input) {
  if (input.tradeActive) {
    return "done";
  }
  if (input.nowMs >= input.deadlineMs) {
    return "give-up";
  }
  if (!input.partnerNear) {
    return "wait";
  }
  return input.nowMs >= input.nextRequestAtMs ? "request" : "wait";
}
function partnerNear(partner) {
  const name = partner.trim();
  if (name.length === 0) {
    return false;
  }
  return Players.query().where((p) => namesMatch2(p.name ?? "", name)).within(DEFAULT_TRADE_RANGE).nearest() !== null;
}
async function openTrade(partner, log) {
  const deadline = performance.now() + MEET_MS;
  let nextRequestAt = 0;
  let waitedFor = false;
  for (;; ) {
    const action = decideOpenTrade({
      tradeActive: Trade.active(),
      partnerNear: partnerNear(partner),
      nowMs: performance.now(),
      deadlineMs: deadline,
      nextRequestAtMs: nextRequestAt
    });
    if (action === "done") {
      return true;
    }
    if (action === "give-up") {
      log(`trade with '${partner}' never opened within ${Math.round(MEET_MS / 1000)}s`);
      return false;
    }
    if (action === "request") {
      if (!await Trade.request(partner)) {
        log(`could not open a trade with '${partner}'`);
        return false;
      }
      nextRequestAt = performance.now() + OPEN_REQUEST_EVERY_MS;
    } else if (!waitedFor && !partnerNear(partner)) {
      log(`waiting for '${partner}' to come back into trade range`);
      waitedFor = true;
    }
    await Execution.delayTicks(2);
  }
}
async function runHandoff(spec) {
  const { partner, id, name, giving, label, log } = spec;
  let confirmed = false;
  const before = Trade.active() ? null : Inventory.countById(id);
  const packReadable = () => Inventory.used() > 0;
  const landed = () => {
    const now = Inventory.countById(id);
    if (!giving) {
      return before === null ? now > 0 : now > before;
    }
    if (Trade.active() || !packReadable()) {
      return false;
    }
    return before === null ? confirmed : now < before;
  };
  if (landed()) {
    return true;
  }
  if (giving && before === 0) {
    log(`nothing to give: no ${name} (${id}) in the pack`);
    return false;
  }
  if (reader.modals().main !== -1) {
    await Modals.close();
  }
  if (!await Traversal.walkResilient(spec.rendezvous, { radius: 2, attempts: 3, timeoutMs: MEET_MS, log })) {
    return false;
  }
  if (!Trade.active() && !await openTrade(partner, log)) {
    return false;
  }
  const deadline = performance.now() + HANDOFF_MS;
  let offered = false;
  let last = "";
  while (performance.now() < deadline) {
    if (!Trade.active()) {
      await Execution.delayTicks(3);
      if (!Trade.active()) {
        break;
      }
    }
    const who = Trade.partner();
    if (who !== null && !namesMatch2(who, partner)) {
      log(`declining a trade from '${who}' — not the configured partner`);
      await Trade.decline();
      return false;
    }
    const screen = Trade.onConfirmScreen() ? "confirm" : "offer";
    const ids = (slots) => slots.map((s) => `${s.id}x${s.count}`).join(",") || "-";
    const state2 = `${screen} modal=${reader.modals().main} want=${id}` + ` mine=[${ids(Trade.myOffer())}] theirs=[${ids(Trade.theirOffer())}]`;
    if (state2 !== last) {
      log(`${label}: ${state2}`);
      last = state2;
    }
    if (Trade.onConfirmScreen()) {
      await Trade.accept();
      confirmed = true;
      await Execution.delayUntil(() => !Trade.active(), SCREEN_MS);
      continue;
    }
    if (giving && !offered) {
      if (!await Trade.offer(name, 1, (slot) => slot.id === id)) {
        log(`could not offer ${name} (${id})`);
        await Trade.decline();
        return false;
      }
      offered = true;
      continue;
    }
    if (!giving && !Trade.theirOffer().some((o) => o.id === id)) {
      await Execution.delayTicks(1);
      continue;
    }
    const clicked = await Trade.accept();
    log(`${label}: accept on ${screen} -> ${clicked}`);
    await Execution.delayUntil(() => Trade.onConfirmScreen() || !Trade.active(), SCREEN_MS);
  }
  await Execution.delayUntil(() => !Trade.active(), SCREEN_MS);
  await Execution.delayTicks(2);
  if (!landed()) {
    log(`${label} did not move a ${name} (offered=${offered} confirmed=${confirmed})`);
    return false;
  }
  log(`${label} moved a ${name}`);
  return true;
}

// src/bot/api/ai/quests/defs/shieldofarrav/partner.ts
var ArravHandoffState = { halvesGiven: 0, gaveCert: false };
function decideHandoff(input) {
  if (!input.partnerConfigured) {
    return null;
  }
  const target = Math.max(1, input.certTarget);
  if (input.gang === "phoenix") {
    if (input.stage >= SOA_STAGE.PHOENIX_JOINED && input.stage < SOA_STAGE.COMPLETE && input.hasKey) {
      return "give-key";
    }
    if (input.hasOwnHalf && input.hasOtherHalf) {
      return null;
    }
    if (!input.gaveCert && input.certsHeld >= 2 && input.certs >= target) {
      return "give-cert";
    }
    if (input.hasOwnHalf) {
      return "take-half";
    }
    return null;
  }
  if (input.stage === SOA_STAGE.KATRINE_TASK && !input.hasKey) {
    return "take-key";
  }
  if (input.hasOwnHalf) {
    return "give-half";
  }
  const covered = input.halvesGiven * 2 >= Math.max(1, input.certTarget);
  if (input.stage === SOA_STAGE.BLACKARM_JOINED && input.certs === 0 && covered) {
    return "take-cert";
  }
  return null;
}
function itemFor(handoff, gang) {
  switch (handoff) {
    case "give-key":
      return { id: SOA_ID.STORE_KEY, name: "Key", giving: true };
    case "take-key":
      return { id: SOA_ID.STORE_KEY, name: "Key", giving: false };
    case "give-half":
      return { id: ownHalf(gang), name: "Broken shield", giving: true };
    case "take-half":
      return { id: otherHalf(gang), name: "Broken shield", giving: false };
    case "give-cert":
      return { id: SOA_ID.CERTIFICATE, name: "Certificate", giving: true };
    case "take-cert":
      return { id: SOA_ID.CERTIFICATE, name: "Certificate", giving: false };
  }
}
async function runHandoff2(handoff, gang, log) {
  const want = itemFor(handoff, gang);
  const moved = await runHandoff({
    partner: ArravConfig.partner,
    rendezvous: SOA_TILE.RENDEZVOUS,
    id: want.id,
    name: want.name,
    giving: want.giving,
    label: handoff,
    log
  });
  if (!moved) {
    return false;
  }
  if (handoff === "give-half") {
    ArravHandoffState.halvesGiven++;
  }
  if (handoff === "give-cert") {
    ArravHandoffState.gaveCert = true;
  }
  return true;
}
function handoffStep(handoff, gang) {
  return {
    kind: "custom",
    name: `${handoff} with ${ArravConfig.partner}`,
    run: (log) => runHandoff2(handoff, gang, log)
  };
}

// src/bot/api/ai/quests/defs/shieldofarrav/certs.ts
async function mintCertificates(log) {
  const before = Inventory.countById(SOA_ID.CERTIFICATE);
  return talkUntil(CURATOR, [], () => Inventory.countById(SOA_ID.CERTIFICATE) > before, log);
}
