// src/bot/api/ai/quests/defs/shieldofarrav/index.ts
var cachedGang = null;
var cachedFor = "";
function gang() {
  const name = Game.myName() ?? "";
  const fingerprint = `${ArravConfig.gang}|${name}`;
  if (cachedGang === null || cachedFor !== fingerprint && name.length > 0) {
    cachedGang = resolveGang(ArravConfig.gang, name.length > 0 ? name : null);
    cachedFor = fingerprint;
  }
  return cachedGang;
}
function decide13(snap) {
  if (snap.journal === "unknown") {
    return { kind: "wait", reason: "quest journal not loaded" };
  }
  if (snap.journal === "complete") {
    return { kind: "done" };
  }
  const stage = snap.progress?.stage ?? snap.stage;
  if (stage === undefined) {
    return { kind: "wait", reason: "quest stage not readable" };
  }
  const mine = gang();
  if (!snap.bankKnown) {
    return { kind: "scanBank" };
  }
  const curator = curatorStep(snap, mine);
  if (curator) {
    return curator;
  }
  const handoff = decideHandoff({
    gang: mine,
    stage,
    hasKey: heldId4(snap, SOA_ID.STORE_KEY) > 0,
    hasOwnHalf: heldId4(snap, ownHalf(mine)) > 0,
    hasOtherHalf: heldId4(snap, otherHalf(mine)) > 0,
    certs: certsHeld(snap) + certsBanked(snap),
    certsHeld: certsHeld(snap),
    certTarget: ArravConfig.certTarget,
    partnerConfigured: ArravConfig.partner.trim().length > 0,
    halvesGiven: ArravHandoffState.halvesGiven,
    gaveCert: ArravHandoffState.gaveCert
  });
  if (handoff) {
    return handoffStep(handoff, mine);
  }
  const certs = certStep(snap, mine);
  if (certs) {
    return certs;
  }
  if (ArravConfig.partner.trim().length === 0 && certsHeld(snap) + certsBanked(snap) === 0 && heldId4(snap, ownHalf(mine)) > 0) {
    return { kind: "wait", reason: "own half held, no partner and no banked certificate: the other gang's half is out of reach alone" };
  }
  return mine === "phoenix" ? phoenixStep(snap) : blackarmStep(snap);
}
var shieldofarrav = {
  record: QUESTS.find((r) => r.id === "blackarmgang"),
  bank: "nearest",
  ownsInventory: true,
  hops: [...SOA_HOPS],
  grind: ["Jonny the beard", "Weaponsmaster"],
  tools: ["coins", "broken shield", "certificate", "key", "scroll", "phoenix crossbow", "book"],
  sustain: { foods: ["Lobster", "Swordfish", "Tuna"], eatBelowHp: 0.5 },
  readProgress: readShieldOfArravProgress,
  warnReadiness: () => ArravConfig.partner.trim().length > 0 ? null : "Shield of Arrav needs a partner or a banked certificate — it cannot be finished alone",
  decide: decide13
};

// src/bot/api/shop/Shop.ts
var SHOP_ROOT = 3824;
var SHOP_STOCK_COM = 3900;
var SHOP_PLAYER_COM = 3823;
var Shop = {
  isOpen() {
    return reader.modals().main === SHOP_ROOT;
  },
  async open(npcName) {
    if (Shop.isOpen()) {
      return true;
    }
    for (let attempt = 0;attempt < 3; attempt++) {
      const npc = Npcs.query().name(npcName).action("Trade").nearest();
      if (!npc) {
        return false;
      }
      await npc.interact("Trade");
      if (await Execution.delayUntil(() => Shop.isOpen(), 3000)) {
        return true;
      }
    }
    return false;
  },
  stock() {
    if (!Shop.isOpen()) {
      return [];
    }
    const out = [];
    for (const s of reader.shopInv(SHOP_STOCK_COM)) {
      if (s.name !== null) {
        out.push({ name: s.name, count: s.count, slot: s.slot });
      }
    }
    return out;
  },
  async buy(name, n) {
    let bought = 0;
    while (bought < n && Shop.isOpen()) {
      const it = reader.shopInv(SHOP_STOCK_COM).find((s) => s.name?.toLowerCase() === name.toLowerCase());
      if (!it || it.count === 0) {
        break;
      }
      const batch = shopOpBatch(it.ops, "buy", n - bought);
      if (batch.length === 0) {
        break;
      }
      const before = countHeld(name);
      for (const opIndex2 of batch) {
        await Input.invButton(it.id, it.slot, it.comId, opIndex2 + 1);
      }
      await Execution.delayUntil(() => countHeld(name) !== before, 3000);
      await Execution.delayTicks(1);
      const got = countHeld(name) - before;
      if (got <= 0) {
        break;
      }
      bought += got;
    }
    return bought;
  },
  async buyById(id, n) {
    let bought = 0;
    while (bought < n && Shop.isOpen()) {
      const it = reader.shopInv(SHOP_STOCK_COM).find((s) => s.id === id);
      if (!it || it.count === 0) {
        break;
      }
      const batch = shopOpBatch(it.ops, "buy", n - bought);
      if (batch.length === 0) {
        break;
      }
      const before = heldById(id);
      for (const opIndex2 of batch) {
        await Input.invButton(it.id, it.slot, it.comId, opIndex2 + 1);
      }
      await Execution.delayUntil(() => heldById(id) !== before, 3000);
      await Execution.delayTicks(1);
      const got = heldById(id) - before;
      if (got <= 0) {
        break;
      }
      bought += got;
    }
    return bought;
  },
  async sell(name, n, pick) {
    let sold = 0;
    while (sold < n && Shop.isOpen()) {
      const matches2 = reader.shopInv(SHOP_PLAYER_COM).filter((s) => s.name?.toLowerCase() === name.toLowerCase());
      const it = pick ? matches2.find(pick) : matches2[0];
      if (!it) {
        break;
      }
      const batch = shopOpBatch(it.ops, "sell", n - sold);
      if (batch.length === 0) {
        break;
      }
      const before = countHeld(name);
      for (const opIndex2 of batch) {
        await Input.invButton(it.id, it.slot, it.comId, opIndex2 + 1);
      }
      await Execution.delayUntil(() => countHeld(name) !== before, 3000);
      await Execution.delayTicks(1);
      const gone = before - countHeld(name);
      if (gone <= 0) {
        break;
      }
      sold += gone;
    }
    return sold;
  },
  async close() {
    if (!Shop.isOpen()) {
      return;
    }
    actions.closeModal();
    await Execution.delayUntil(() => !Shop.isOpen(), 3000);
  }
};
function countHeld(name) {
  return Inventory.count(name);
}
function heldById(id) {
  return Inventory.items().filter((item) => item.id === id).reduce((sum, item) => sum + item.count, 0);
}
var USER_OPS_PER_TICK = 5;
var SHOP_STEPS = [10, 5, 1];
function shopOpBatch(ops, verb, remaining) {
  const batch = [];
  let left = remaining;
  while (batch.length < USER_OPS_PER_TICK && left > 0) {
    const step = SHOP_STEPS.find((size) => size <= left && ops.some((o) => o?.toLowerCase() === `${verb} ${size}`));
    if (step === undefined) {
      break;
    }
    batch.push(ops.findIndex((o) => o?.toLowerCase() === `${verb} ${step}`));
    left -= step;
  }
  return batch;
}

// src/bot/api/ai/quests/engine/provisioning.ts
function planProvisioning(items, inv, bank) {
  const plan = { withdraw: [], gather: [], blocked: [], satisfied: true };
  for (const item of items) {
    const key = item.name.toLowerCase();
    const have2 = inv.get(key) ?? 0;
    if (have2 >= item.qty) {
      continue;
    }
    plan.satisfied = false;
    let short = item.qty - have2;
    const banked3 = bank.get(key) ?? 0;
    if (banked3 > 0) {
      const take = Math.min(short, banked3);
      plan.withdraw.push({ name: item.name, qty: take });
      short -= take;
    }
    if (short > 0) {
      if (item.kind === "mustHave") {
        plan.blocked.push(`${item.name} x${item.qty}`);
      } else {
        plan.gather.push({ name: item.name, need: short });
      }
    }
  }
  return plan;
}
var COIN_FLOAT3 = 1000;
var BUY_TOPUP_DIVISOR = 4;
function buyPurseTopUp(held7, estGp) {
  const target = Math.max(estGp, COIN_FLOAT3);
  return held7 >= Math.ceil(target / BUY_TOPUP_DIVISOR) ? { need: false, draw: 0 } : { need: true, draw: target - held7 };
}
function shouldFreshenPack(journal, usedSlots, alreadyFresh) {
  if (usedSlots === 0 || alreadyFresh) {
    return false;
  }
  return journal === "notStarted";
}
function floatDrawPlan(held7, banked3, target, alreadyDrawn) {
  if (alreadyDrawn || held7 >= target) {
    return { qty: 0, drawn: true };
  }
  return { qty: Math.max(0, Math.min(target - held7, banked3)), drawn: false };
}
function depositPlan(inv, keep) {
  return [...inv.keys()].filter((name) => !keep.some((k) => name.includes(k)));
}
function gpShort2(snap, estGp) {
  const have2 = (snap.inv.get("coins") ?? 0) + snap.bankCoins;
  return Math.max(0, estGp - have2);
}
function floatWithdraw(inv, bank, name, target) {
  const key = name.toLowerCase();
  const pack = inv.get(key) ?? 0;
  const banked3 = bank.get(key) ?? 0;
  const want = Math.min(target - pack, banked3);
  return want > 0 ? { name, qty: want } : null;
}
function coinFloatWithdraw(inv, bank, float) {
  return floatWithdraw(inv, bank, "Coins", float);
}
function isAcquireStep(step) {
  return step.kind === "buy" || step.kind === "grabGround" || step.kind === "pickLoc" || step.kind === "mineRock";
}
function isWalkStep(step) {
  return isAcquireStep(step) || step.kind === "talk" || step.kind === "interactLoc" || step.kind === "useOn" || step.kind === "equip";
}
function shouldScanBankFirst(bankKnown, step, teleportsOn) {
  if (bankKnown) {
    return false;
  }
  if (isAcquireStep(step)) {
    return true;
  }
  return teleportsOn && isWalkStep(step);
}
function acquireNeed(step, inv) {
  const name = step.item;
  if (!name) {
    return null;
  }
  const have2 = inv.get(name.toLowerCase()) ?? 0;
  if (step.kind === "buy") {
    const qty = step.qty ?? 1;
    return qty > have2 ? { name, qty: qty - have2 } : null;
  }
  if (step.kind === "grabGround" || step.kind === "pickLoc") {
    return { name, qty: 1 };
  }
  if (step.kind === "mineRock") {
    const qty = step.qty ?? 1;
    return qty > have2 ? { name, qty: qty - have2 } : null;
  }
  return null;
}
function preferBankWithdraw(step, snap) {
  if (!snap.bankKnown || !isAcquireStep(step)) {
    return null;
  }
  const need = acquireNeed(step, snap.inv);
  if (!need) {
    return null;
  }
  const banked3 = snap.bank?.get(need.name.toLowerCase()) ?? 0;
  const take = Math.min(need.qty, banked3);
  return take > 0 ? { name: need.name, qty: take } : null;
}

// src/bot/api/ai/quests/exec/steps.ts
var BANK_CANDIDATES = 6;
async function reachableBank(from, log) {
  const candidates = nearestBanks(from).slice(0, BANK_CANDIDATES);
  let best = null;
  for (const bank of candidates) {
    if (best !== null && bankDistance(from, bank.tile) >= best.cost) {
      break;
    }
    const path = await Navigator.findPath(from, bank.tile);
    if (path.ok && (best === null || path.cost < best.cost)) {
      best = { tile: bank.tile, cost: path.cost };
    }
  }
  if (best) {
    return best.tile;
  }
  log(`no bank answered a path from (${from.x},${from.z}), trying the closest anyway`);
  return candidates[0]?.tile;
}
async function openBankLeg(noBankMsg, override, log) {
  const here2 = Game.tile();
  const bankTile = override ?? (here2 ? await reachableBank(here2, log) : undefined);
  if (!bankTile) {
    log(noBankMsg);
    return false;
  }
  return Banking.open({ stand: bankTile, log });
}
async function ensureAt(anchor, radius, log) {
  const here2 = Game.tile();
  if (here2 && here2.level === anchor.level && anchor.distanceTo(here2) <= radius) {
    return true;
  }
  return Traversal.walkResilient(anchor, { radius, attempts: 3, timeoutMs: 90000, log });
}
async function executeStep(step, hops, log) {
  switch (step.kind) {
    case "talk": {
      if (!await gotoNpc(step.stop, hops, log)) {
        return false;
      }
      if (step.stop.npc === "Joe" && Inventory.contains("Beer")) {
        const beer = Inventory.first("Beer");
        const joe = Npcs.query().name("Joe").within(6).nearest();
        if (beer && joe) {
          log("using Beer on Joe the guard");
          if (await beer.useOn(joe)) {
            if (await Execution.delayUntil(() => ChatDialog.isOpen() || ChatDialog.canContinue(), 4000)) {
              return driveDialog(step.stop.prefer, log, step.stop.gapMs);
            }
          }
        }
      }
      return talkThrough(step.stop.npc, step.stop.prefer, log, step.stop.gapMs);
    }
    case "grabGround": {
      const before = Inventory.count(step.item);
      const g = GroundItems.query().name(step.item).within(12).nearest();
      if (!g) {
        const arrived = await ensureAt(step.anchor, 2, log);
        if (arrived && step.waitIfMissing) {
          await Execution.delayTicks(2);
          return false;
        }
        return arrived;
      }
      if (!await g.interact("Take")) {
        return false;
      }
      return Execution.delayUntil(() => Inventory.count(step.item) > before, 8000);
    }
    case "pickLoc": {
      const before = Inventory.count(step.item);
      const loc = Locs.query().name(step.loc).action(step.op).within(10).nearest();
      if (!loc) {
        return ensureAt(step.anchor, 2, log);
      }
      if (!await loc.interact(step.op)) {
        return false;
      }
      return Execution.delayUntil(() => Inventory.count(step.item) > before, 8000);
    }
    case "interactLoc": {
      const loc = Locs.query().name(step.loc).action(step.op).within(10).nearest();
      if (!loc) {
        return ensureAt(step.anchor, 2, log);
      }
      if (!await loc.interact(step.op)) {
        return false;
      }
      if (step.expectItem !== undefined) {
        const item = step.expectItem;
        return Execution.delayUntil(() => Inventory.contains(item), 8000);
      }
      await Execution.delayTicks(3);
      return true;
    }
    case "useOn": {
      if (step.targetKind === "item") {
        const held8 = Inventory.first(step.item);
        if (!held8) {
          log(`useOn: no '${step.item}' in the pack`);
          return false;
        }
        const targetItem = Inventory.first(step.target);
        if (!targetItem) {
          log(`useOn: no '${step.target}' in the pack`);
          return false;
        }
        const beforeProduct2 = step.product !== undefined ? Inventory.count(step.product) : 0;
        if (!await held8.useOn(targetItem)) {
          return false;
        }
        if (step.product !== undefined) {
          const product = step.product;
          return Execution.delayUntil(() => Inventory.count(product) > beforeProduct2, 1e4);
        }
        await Execution.delayTicks(3);
        return true;
      }
      if (!await ensureAt(step.anchor, 4, log)) {
        return false;
      }
      const held7 = Inventory.first(step.item);
      if (!held7) {
        log(`useOn: no '${step.item}' in the pack`);
        return false;
      }
      const target = step.targetKind === "npc" ? Npcs.query().name(step.target).within(10).nearest() : Locs.query().name(step.target).within(10).nearest();
      if (!target) {
        log(`useOn: no '${step.target}' near the anchor`);
        return false;
      }
      const beforeProduct = step.product !== undefined ? Inventory.count(step.product) : 0;
      if (!await held7.useOn(target)) {
        return false;
      }
      if (step.product !== undefined) {
        const product = step.product;
        return Execution.delayUntil(() => Inventory.count(product) > beforeProduct, 1e4);
      }
      await Execution.delayTicks(3);
      return true;
    }
    case "equip":
      return Equipment.equip(step.item);
    case "scanBank": {
      if (!await openBankLeg("scanBank: no known bank", step.bank, log)) {
        return false;
      }
      await Execution.delayUntil(() => Bank.loaded(), 3000);
      return Bank.isOpen();
    }
    case "withdraw": {
      if (!await openBankLeg("withdraw: no known bank", step.bank, log)) {
        return false;
      }
      let ok = true;
      for (const it of step.items) {
        const withdrawn = it.id === undefined ? await Bank.withdrawX(it.name, it.qty) : await Bank.withdrawXById(it.id, it.qty);
        if (!withdrawn) {
          const exact = it.id === undefined ? "" : ` (id ${it.id})`;
          log(`withdraw: '${it.name}'${exact} x${it.qty} failed`);
          ok = false;
        }
      }
      if (!step.leaveOpen) {
        await Modals.close();
      }
      return ok;
    }
    case "deposit": {
      if (!await openBankLeg("deposit: no known bank", step.bank, log)) {
        return false;
      }
      const keepIds = new Set(step.keepIds ?? []);
      const kept = (name, id) => {
        if (keepIds.has(id)) {
          return true;
        }
        const n = name.toLowerCase();
        return step.keep.some((k) => step.exactKeep ? n === k.toLowerCase() : n.includes(k.toLowerCase()));
      };
      await Bank.depositAllMatching((name, id) => !kept(name, id));
      if (!step.leaveOpen) {
        await Modals.close();
      }
      return true;
    }
    case "buy": {
      const before = Inventory.count(step.item);
      const purse = buyPurseTopUp(Inventory.count("Coins"), step.estGp);
      if (purse.need) {
        if (!await openBankLeg("buy: no known bank for coins", step.bank, log)) {
          return false;
        }
        await Bank.withdrawX("Coins", purse.draw);
        await Modals.close();
        if (Inventory.count("Coins") < step.estGp) {
          log(`buy: bank could not cover ${step.estGp} gp for ${step.item}`);
          return false;
        }
      }
      if (!await ensureAt(step.shop.anchor, 3, log)) {
        return false;
      }
      if (!await Shop.open(step.shop.npc)) {
        const keeper = Npcs.query().name(step.shop.npc).action("Trade").nearest();
        if (!keeper || !await Traversal.walkResilient(keeper.tile(), { radius: 1, attempts: 3, timeoutMs: 45000, log })) {
          log(`buy: could not open ${step.shop.npc}'s shop near the anchor`);
          return false;
        }
        if (!await Shop.open(step.shop.npc)) {
          log(`buy: could not open ${step.shop.npc}'s shop near the anchor`);
          return false;
        }
      }
      await Shop.buy(step.item, step.qty);
      await Shop.close();
      return Inventory.count(step.item) > before;
    }
    case "mineRock": {
      const before = Inventory.count(step.item);
      const rockType = step.rock.replace(/ ore$/i, "");
      const rockIds = ROCK_TYPES[rockType] ?? QUEST_ROCK_TYPES[rockType];
      if (!rockIds) {
        log(`mineRock: no rock-id mapping for '${rockType}'`);
        return false;
      }
      const idSet = new Set(rockIds);
      const rock = Locs.query().where((l) => idSet.has(l.id)).action("Mine").within(10).nearest();
      if (!rock) {
        return ensureAt(step.anchor, 3, log);
      }
      if (!await rock.interact("Mine")) {
        return false;
      }
      return Execution.delayUntil(() => Inventory.count(step.item) > before, 20000);
    }
    case "custom":
      return step.run(log);
    case "wait":
      await Execution.delayTicks(2);
      return true;
    case "done":
      return true;
  }
}

