// src/bot/api/ai/quests/defs/witchshouse/garden.ts
var WALK_MS4 = 180000;
var FIGHT_MS = 300000;
var SPAWN_TICKS = 25;
var KILLED = /kill the shapeshifter once and for all/i;
var NOTHING_IN_FOUNTAIN = /nothing in the fountain/i;
function experiment() {
  return Npcs.query().where((n) => EXPERIMENT_IDS.includes(n.id)).action("Attack").within(14).nearest();
}
async function fountainKey(log) {
  if (held8(WH_OBJ.SHED_KEY) > 0) {
    return true;
  }
  if (!await Traversal.walkResilient(WH_TILE.FOUNTAIN, { radius: 1, attempts: 3, timeoutMs: WALK_MS4, log })) {
    log(inGarden(Game.tile()) ? "stopped short of the fountain inside the garden" : "never reached the garden. The witch throws a caught bot back to the boy");
    return false;
  }
  await settleScene();
  const took = await promptLoc({
    name: "Fountain",
    op: "Check",
    near: WH_TILE.FOUNTAIN,
    id: WH_LOC.FOUNTAIN,
    within: 6,
    expect: () => held8(WH_OBJ.SHED_KEY) > 0,
    expectMs: 12000,
    refused: NOTHING_IN_FOUNTAIN
  }, log);
  await Modals.close();
  return took && held8(WH_OBJ.SHED_KEY) > 0;
}
async function enterShed(log) {
  if (inShed(Game.tile())) {
    return true;
  }
  if (held8(WH_OBJ.SHED_KEY) === 0) {
    log("no shed key in the pack. The witch deletes it when she catches you");
    return false;
  }
  return crossTeleportDoor({
    id: WH_LOC.SHED_DOOR,
    stand: WH_TILE.SHED_DOOR,
    standRadius: 0,
    useItem: WH_OBJ.SHED_KEY,
    isFar: () => inShed(Game.tile()),
    log
  });
}
function ballDrop() {
  return GroundItems.query().where((g) => g.id === WH_OBJ.BALL).within(10).nearest();
}
async function summonExperiment(log) {
  const ball = ballDrop();
  if (!ball) {
    log("no ball in the shed to draw the shapeshifter out with");
    return false;
  }
  if (!await ball.interact("Take")) {
    return false;
  }
  const came = await Execution.delayUntil(() => experiment() !== null, 8000);
  await clearBoxes();
  if (!came) {
    log("the ball raised no shapeshifter");
  }
  return came;
}
async function fightExperiment(log) {
  const mark = GameMessages.mark();
  const won = () => GameMessages.sawSince(mark, KILLED);
  Game.setAutoRetaliate(true);
  const deadline = performance.now() + FIGHT_MS;
  let attacking = -1;
  let idle = 0;
  let swings = 0;
  let forms = 0;
  let shape = -1;
  let reported = -1;
  while (performance.now() < deadline) {
    if (won()) {
      log(`the shapeshifter is dead after ${forms} transformations and ${swings} attacks`);
      return true;
    }
    if (EventSignal.pending()) {
      log("yielding the fight to a random event");
      return false;
    }
    await Sustain.run();
    const target = experiment();
    if (!target) {
      if (++idle > SPAWN_TICKS) {
        log(`no shapeshifter for ${SPAWN_TICKS} ticks and no kill message, so the chain broke`);
        return false;
      }
      await Execution.delayTicks(1);
      continue;
    }
    if (shape !== -1 && target.id !== shape) {
      forms++;
    }
    shape = target.id;
    idle = 0;
    const tick = Game.tick();
    if (tick - reported >= 40) {
      reported = tick;
      log(`shapeshifter ${target.id}: hp=${Skills.effective("hitpoints")}/${Skills.level("hitpoints")} attacks=${swings}`);
    }
    if (target.index !== attacking || !Game.inCombat()) {
      if (await target.interact("Attack")) {
        attacking = target.index;
        swings++;
      }
    }
    await Execution.delayTicks(1);
  }
  log(`the shapeshifter outlived ${FIGHT_MS / 1000}s of combat`);
  return false;
}
async function killExperiment(log) {
  if (!await enterShed(log)) {
    return false;
  }
  await settleScene();
  if (!experiment() && !await summonExperiment(log)) {
    return false;
  }
  return fightExperiment(log);
}
async function takeBall(log) {
  if (held8(WH_OBJ.BALL) > 0) {
    return true;
  }
  if (!inShed(Game.tile())) {
    if (!await crossTeleportDoor({
      id: WH_LOC.SHED_DOOR,
      stand: WH_TILE.SHED_DOOR,
      standRadius: 0,
      isFar: () => inShed(Game.tile()),
      log
    })) {
      return false;
    }
  }
  if (!await Traversal.walkResilient(WH_TILE.BALL, { radius: 1, attempts: 2, timeoutMs: 60000, log })) {
    return false;
  }
  await settleScene();
  const ball = ballDrop();
  if (!ball) {
    log("no ball on the shed floor. It respawns on its map timer");
    return false;
  }
  if (!await ball.interact("Take")) {
    return false;
  }
  return Execution.delayUntil(() => held8(WH_OBJ.BALL) > 0, 8000);
}

// src/bot/api/ai/quests/defs/witchshouse/journal.ts
var WH_STAGE = {
  NOT_STARTED: 0,
  STARTED: 1,
  FOUND_MAGNET: 2,
  UNLOCKED_DOOR: 3,
  READ_DIARY: 5,
  DEFEATED: 6,
  COMPLETE: 7
};
function normalize6(lines) {
  return " " + (typeof lines === "string" ? lines : lines.join(" ")).replace(/@[a-z0-9]{3}@/gi, " ").replace(/[|\s]+/g, " ").trim().toLowerCase();
}
var STAGES2 = [
  [" quest complete!", WH_STAGE.COMPLETE],
  [" now the shapeshifter is dead", WH_STAGE.DEFEATED],
  [" i have worked out how to unlock the back door", WH_STAGE.UNLOCKED_DOOR],
  [" i have found a magnet in a cupboard", WH_STAGE.FOUND_MAGNET],
  [" i should find a way into the garden", WH_STAGE.STARTED],
  [" i can start this quest", WH_STAGE.NOT_STARTED]
];
function parseWitchsHouseJournal(lines) {
  const text = normalize6(lines);
  const hit = STAGES2.find(([needle]) => text.includes(needle));
  return hit ? { stage: hit[1], flags: new Set } : undefined;
}
async function readWitchsHouseProgress() {
  const status = Quests.status(WITCHS_HOUSE_QUEST);
  if (status === "complete") {
    return { stage: WH_STAGE.COMPLETE, flags: new Set };
  }
  if (status === "notStarted") {
    return { stage: WH_STAGE.NOT_STARTED, flags: new Set };
  }
  if (status !== "inProgress") {
    return;
  }
  const progress = parseWitchsHouseJournal(await Quests.journal(WITCHS_HOUSE_QUEST));
  if (reader.modals().main !== -1) {
    actions.closeModal();
    await Execution.delayTicks(1);
  }
  return progress;
}

