// src/bot/api/ai/quests/defs/druidicritual.ts
var DRUIDIC_RITUAL_STAGE = {
  NOT_STARTED: 0,
  STARTED: 1,
  SPOKEN_TO_SANFEW: 2,
  GIVEN_INGREDIENTS: 3,
  COMPLETE: 4
};
function parseDruidicRitualJournal(lines) {
  const text = (typeof lines === "string" ? lines : lines.join(" ")).replace(/@[a-z0-9]{3}@/gi, " ").replace(/[|\s]+/g, " ").trim().toLowerCase();
  if (text.includes("quest complete!"))
    return DRUIDIC_RITUAL_STAGE.COMPLETE;
  if (text.includes("gave them to sanfew") || text.includes("claim my reward"))
    return DRUIDIC_RITUAL_STAGE.GIVEN_INGREDIENTS;
  if (text.includes("sanfew told me for the ritual"))
    return DRUIDIC_RITUAL_STAGE.SPOKEN_TO_SANFEW;
  if (text.includes("i should speak to sanfew"))
    return DRUIDIC_RITUAL_STAGE.STARTED;
  if (text.includes("i can start this quest"))
    return DRUIDIC_RITUAL_STAGE.NOT_STARTED;
  return;
}
async function readDruidicRitualStage() {
  const status = Quests.status("Druidic Ritual");
  if (status === "complete")
    return DRUIDIC_RITUAL_STAGE.COMPLETE;
  if (status === "notStarted")
    return DRUIDIC_RITUAL_STAGE.NOT_STARTED;
  if (status !== "inProgress")
    return;
  const lines = await Quests.journal("Druidic Ritual");
  const stage = parseDruidicRitualJournal(lines);
  if (reader.modals().main !== -1) {
    actions.closeModal();
    await Execution.delayTicks(1);
  }
  return stage;
}
