var LOST_CITY_STAGE = {
  NOT_STARTED: 0,
  STARTED: 1,
  SPOKEN_TO_SHAMUS: 2,
  SPIRIT_DEFEATED: 3,
  BRANCH_CUT: 4,
  STAFF_MADE: 5,
  COMPLETE: 6
};
function parseLostCityJournal(lines) {
  const text = (typeof lines === "string" ? lines : lines.join(" ")).replace(/@[a-z0-9]{3}@/gi, " ").replace(/[|\s]+/g, " ").trim().toLowerCase();
  if (text.includes("quest complete!"))
    return LOST_CITY_STAGE.COMPLETE;
  if (text.includes("crafted a dramen staff"))
    return LOST_CITY_STAGE.STAFF_MADE;
  if (text.includes("i should craft the branch from the tree into a staff"))
    return LOST_CITY_STAGE.BRANCH_CUT;
  if (text.includes("with the spirit defeated i can cut a branch"))
    return LOST_CITY_STAGE.SPIRIT_DEFEATED;
  if (text.includes("i can find a dramen tree"))
    return LOST_CITY_STAGE.SPOKEN_TO_SHAMUS;
  if (text.includes("apparently there is a leprechaun"))
    return LOST_CITY_STAGE.STARTED;
  if (text.includes("i can start this quest"))
    return LOST_CITY_STAGE.NOT_STARTED;
  return;
}
async function readLostCityStage() {
  const status = Quests.status("Lost City");
  if (status === "complete")
    return LOST_CITY_STAGE.COMPLETE;
  if (status === "notStarted")
    return LOST_CITY_STAGE.NOT_STARTED;
  if (status !== "inProgress")
    return;
  const lines = await Quests.journal("Lost City");
  const stage = parseLostCityJournal(lines);
  if (reader.modals().main !== -1) {
    actions.closeModal();
    await Execution.delayTicks(1);
  }
  return stage;
}
