var VARROCK_FUNDING_MAN2 = new Tile(3240, 3405, 0);
var AL_KHARID_FUNDING_MAN2 = new Tile(3279, 3188, 0);
var KEBAB_SELLER3 = new Tile(3272, 3182, 0);
