function parseVampireSlayerJournal(lines) {
  const text = (typeof lines === "string" ? lines : lines.join(" ")).replace(/@[a-z0-9]{3}@/gi, " ").replace(/[|\s]+/g, " ").trim().toLowerCase();
  if (text.includes("quest complete!"))
    return VAMPIRE_SLAYER_STAGE.COMPLETE;
  if (text.includes("i have spoken to dr harlow") || text.includes("dr harlow gave me a stake")) {
    return VAMPIRE_SLAYER_STAGE.SPOKEN_TO_HARLOW;
  }
  if (text.includes("i need to speak to dr harlow"))
    return VAMPIRE_SLAYER_STAGE.STARTED;
  if (text.includes("i can start this quest"))
    return VAMPIRE_SLAYER_STAGE.NOT_STARTED;
  return;
}
async function readVampireSlayerStage() {
  const status = Quests.status("Vampire Slayer");
  if (status === "complete")
    return VAMPIRE_SLAYER_STAGE.COMPLETE;
  if (status === "notStarted")
    return VAMPIRE_SLAYER_STAGE.NOT_STARTED;
  if (status !== "inProgress")
    return;
  const lines = await Quests.journal("Vampire Slayer");
  const stage = parseVampireSlayerJournal(lines);
  if (reader.modals().main !== -1) {
    actions.closeModal();
    await Execution.delayTicks(1);
  }
  return stage;
}
