function watchtowerArea(tile) {
  if (!tile)
    return "unknown";
  const { x: x2, z, level } = tile;
  if (x2 >= 2900 && x2 <= 2960 && z >= 4670 && z <= 4740)
    return "mirrorTower";
  if (z >= 9400 && z <= 9480 && x2 >= 2490 && x2 <= 2540)
    return "skavidCaves";
  if (z >= 9400 && z <= 9480 && x2 >= 2560 && x2 <= 2623)
    return "enclave";
  if (level === 2 && x2 >= 2540 && x2 <= 2552 && z >= 3108 && z <= 3120)
    return "towerFloor";
  if (x2 >= 2505 && x2 <= 2519 && z >= 3079 && z <= 3092)
    return "grewIsland";
  if (x2 >= 2565 && x2 <= 2585 && z >= 3015 && z <= 3040)
    return "tobanCamp";
  if (x2 >= 2527 && x2 <= 2545 && z >= 3027 && z <= 3036)
    return "cityGuard";
  if (x2 >= 2508 && x2 <= 2532 && z >= 3005 && z <= 3026)
    return "lowerCity";
  return "yanille";
}

