// src/bot/api/ai/quests/defs/watchtower/journal.ts
var WATCHTOWER_STAGE = {
  NOT_STARTED: 0,
  STARTED: 1,
  GIVEN_FINGERNAILS: 2,
  MADE_RELIC: 3,
  GIVEN_RELIC: 4,
  GIVEN_RIDDLE: 5,
  SOLVED_RIDDLE: 6,
  SKAVID_CRYSTAL: 7,
  FED_NIGHTSHADE: 8,
  LEARNED_POTION: 9,
  MADE_POTION: 10,
  FOUND_ALL_CRYSTALS: 11,
  COMPLETE: 13,
  READ_SCROLL: 14
};
var WATCHTOWER_QUEST = "Watch Tower";
function normalize9(lines) {
  return (typeof lines === "string" ? lines : lines.join(" ")).replace(/@[a-z0-9]{3}@/gi, " ").replace(/[|\s]+/g, " ").trim().toLowerCase();
}
var FLAG_LINES = [
  ["i returned og's stolen gold", "helped-og"],
  ["og wants me to", "spoken-og"],
  ["i have og's", "spoken-og"],
  ["i knocked out one of gorad's teeth", "helped-grew"],
  ["grew wants me to", "spoken-grew"],
  ["i have one of gorad's teeth", "spoken-grew"],
  ["i gave the bones to toban", "helped-toban"],
  ["toban wants the", "spoken-toban"],
  ["i have the dragon bones", "spoken-toban"],
  ["the north west guard wants", "looking-relic"],
  ["the north-east guard wants", "market-asked"],
  ["i gave the north-east guard a rock cake", "market-paid"],
  ["i have it with me now, so i can navigate", "has-map"],
  ["i have been taught a few words", "learning-skavid"],
  ["'cur bidith' - 'ig'", "learned-ig"],
  ["'gor cur' - 'ar'", "learned-ar"],
  ["'bidith tanath' - 'cur'", "learned-cur"],
  ["'gor nod' - 'nod'", "learned-nod"],
  ["i have mined the sacred rock", "mined-rock"]
];
var IMPLIED = [
  ["helped-og", "spoken-og"],
  ["helped-grew", "spoken-grew"],
  ["helped-toban", "spoken-toban"]
];
function readFlags2(text) {
  const flags = new Set;
  for (const [needle, flag] of FLAG_LINES) {
    if (text.includes(needle)) {
      flags.add(flag);
    }
  }
  for (const [source, implied] of IMPLIED) {
    if (flags.has(source)) {
      flags.add(implied);
    }
  }
  const kills = text.match(/kill (\d+) ogre shaman/);
  if (kills) {
    flags.add("shamans-left:" + kills[1]);
  } else if (text.includes("i killed all the ogre shamans")) {
    flags.add("shamans-left:0");
  }
  return flags;
}
function readStage5(text) {
  if (text.includes("quest complete!"))
    return WATCHTOWER_STAGE.COMPLETE;
  if (text.includes("i have taken the crystals to the watchtower wizard"))
    return WATCHTOWER_STAGE.FOUND_ALL_CRYSTALS;
  if (text.includes("he infused it into a magic ogre potion"))
    return WATCHTOWER_STAGE.MADE_POTION;
  if (text.includes("i need to get it enchanted") || text.includes("i need to make the")) {
    return WATCHTOWER_STAGE.LEARNED_POTION;
  }
  if (text.includes("i need to defeat the ogre shamans and find the other"))
    return WATCHTOWER_STAGE.FED_NIGHTSHADE;
  if (text.includes("the other crystals are in the shamans' enclave"))
    return WATCHTOWER_STAGE.SKAVID_CRYSTAL;
  if (text.includes("i was given a map by the guard"))
    return WATCHTOWER_STAGE.SOLVED_RIDDLE;
  if (text.includes("some guards gave me a puzzle"))
    return WATCHTOWER_STAGE.GIVEN_RIDDLE;
  if (text.includes("i gave the ogre relic to the north west guard"))
    return WATCHTOWER_STAGE.GIVEN_RELIC;
  if (text.includes("now i need to deal with the tribal ogres"))
    return WATCHTOWER_STAGE.GIVEN_FINGERNAILS;
  if (text.includes("i accepted the challenge of finding the lost"))
    return WATCHTOWER_STAGE.STARTED;
  if (text.includes("i can start this quest"))
    return WATCHTOWER_STAGE.NOT_STARTED;
  return;
}
function parseWatchtowerJournal(lines) {
  const text = normalize9(lines);
  const stage = readStage5(text);
  return stage === undefined ? undefined : { stage, flags: readFlags2(text) };
}
async function readWatchtowerProgress() {
  const status = Quests.status(WATCHTOWER_QUEST);
  if (status === "complete")
    return { stage: WATCHTOWER_STAGE.COMPLETE, flags: new Set };
  if (status === "notStarted")
    return { stage: WATCHTOWER_STAGE.NOT_STARTED, flags: new Set };
  if (status !== "inProgress")
    return;
  const progress = parseWatchtowerJournal(await Quests.journal(WATCHTOWER_QUEST));
  if (reader.modals().main !== -1) {
    actions.closeModal();
    await Execution.delayTicks(1);
  }
  return progress;
}

