var FURNACE_COLD = /furnace is cold/i;
var FURNACE_NEEDS_HEAT = /needs to be hotter/i;
var FURNACE_NEED_COAL = /need four heaps of coal/i;
var AIR_PUMPING = /bellows pump air/i;
var AIR_STOPPED = /bellows stop pumping/i;
var AIR_NOTHING = /nothing happens; the lever resets/i;
async function pullAirLever(log) {
  if (!await walkNear(BELLOWS_STAND, 3, log)) {
    return "fail";
  }
  await settleScene();
  const lever = Locs.query().name("Lever").action("Pull").within(12).results().sort((a, b) => dist2(a.tile(), BELLOWS_STAND) - dist2(b.tile(), BELLOWS_STAND))[0];
  if (!lever) {
    log("no air-chamber Lever to Pull");
    return "fail";
  }
  const mark = GameMessages.mark();
  log("pulling the air-chamber Lever to pump the bellows");
  if (!await lever.interact("Pull")) {
    return "fail";
  }
  await Execution.delayUntil(() => GameMessages.sawSince(mark, AIR_PUMPING) || GameMessages.sawSince(mark, AIR_STOPPED) || GameMessages.sawSince(mark, AIR_NOTHING), 5000);
  if (GameMessages.sawSince(mark, AIR_PUMPING)) {
    return "on";
  }
  if (GameMessages.sawSince(mark, AIR_STOPPED)) {
    return "off";
  }
  if (GameMessages.sawSince(mark, AIR_NOTHING)) {
    return "nothing";
  }
  return "fail";
}
async function ensureMeleeWeapon(log) {
  if (Equipment.items().some((i2) => {
    const n = i2.name?.toLowerCase() ?? "";
    return n.includes("scimitar") || n.includes("sword") || n.includes("battleaxe") || n.includes("dagger");
  })) {
    return;
  }
  const weapon = Inventory.items().find((i2) => {
    const n = i2.name?.toLowerCase() ?? "";
    return (n.includes("scimitar") || n.includes("sword") || n.includes("battleaxe") || n.includes("dagger")) && i2.actions().some((a) => /wield|wear|equip/i.test(a));
  });
  if (!weapon?.name) {
    log("no melee weapon in pack — fighting unarmed");
    return;
  }
  log(`wielding ${weapon.name}`);
  await Equipment.equip(weapon.name);
}
function nearRockPocket(tile) {
  if (!tile) {
    return false;
  }
  return tile.x >= 2688 && tile.x <= 2714 && tile.z >= 9875 && tile.z <= 9910;
}
function earthAtRock() {
  return Npcs.query().name(EARTH_ELEMENTAL).where((n) => !n.targetsAnotherPlayer() && nearRockPocket(n.tile())).within(20).nearest();
}
function findOreOnGround() {
  return GroundItems.query().where((g) => g.id === EW_ITEM.ELEMENTAL_ORE.id).within(24).nearest() ?? GroundItems.query().name(EW_ITEM.ELEMENTAL_ORE.name).within(24).nearest();
}
async function takeElementalOre(log) {
  if (heldId(EW_ITEM.ELEMENTAL_ORE.id) > 0) {
    return true;
  }
  await Execution.delayUntil(() => findOreOnGround() !== null || heldId(EW_ITEM.ELEMENTAL_ORE.id) > 0, 1e4);
  if (heldId(EW_ITEM.ELEMENTAL_ORE.id) > 0) {
    return true;
  }
  for (let attempt = 0;attempt < 5; attempt++) {
    const ground = findOreOnGround();
    if (!ground) {
      await Execution.delayTicks(2);
      continue;
    }
    const t = ground.tile();
    log(`taking Elemental ore at (${t.x},${t.z}) attempt ${attempt + 1}`);
    if (Game.tile() && ground.distance() > 2) {
      await walkNear(new Tile(t.x, t.z, t.level), 1, log);
      await settleScene();
    }
    const live = findOreOnGround();
    if (!live) {
      continue;
    }
    const before = heldId(EW_ITEM.ELEMENTAL_ORE.id);
    if (!await live.interact("Take")) {
      await Execution.delayTicks(1);
      continue;
    }
    if (await Execution.delayUntil(() => heldId(EW_ITEM.ELEMENTAL_ORE.id) > before, 6000)) {
      return true;
    }
    await Execution.delayTicks(1);
  }
  return heldId(EW_ITEM.ELEMENTAL_ORE.id) > 0;
}
async function freeSlotForOre(log) {
  if (!Inventory.isFull()) {
    return;
  }
  const keep = new Set([
    EW_ITEM.BATTERED_BOOK.id,
    EW_ITEM.BATTERED_KEY.id,
    EW_ITEM.ELEMENTAL_ORE.id,
    EW_ITEM.ELEMENTAL_METAL.id,
    EW_ITEM.STONE_BOWL.id,
    EW_ITEM.STONE_BOWL_FULL.id,
    EW_ITEM.KNIFE.id,
    EW_ITEM.HAMMER.id,
    EW_ITEM.NEEDLE.id,
    EW_ITEM.THREAD.id,
    EW_ITEM.LEATHER.id,
    EW_ITEM.COAL.id,
    EW_ITEM.COINS.id,
    1265,
    1267,
    1269,
    1271,
    1273,
    1275
  ]);
  const food = Inventory.items().find((i2) => {
    const n = i2.name?.toLowerCase() ?? "";
    return (n.includes("lobster") || n.includes("swordfish") || n.includes("salmon") || n.includes("trout")) && i2.actions().some((a) => a.toLowerCase() === "drop");
  });
  const junk = food ?? Inventory.items().find((i2) => i2.id !== undefined && !keep.has(i2.id) && i2.actions().some((a) => a.toLowerCase() === "drop"));
  if (!junk) {
    log("inventory full and nothing safe to drop for Elemental ore");
    return;
  }
  log(`dropping ${junk.name ?? junk.id} to free a slot for ore`);
  await junk.interact("Drop");
  await Execution.delayUntil(() => !Inventory.isFull(), 3000);
}
async function mineElementalOre(log) {
  if (heldId(EW_ITEM.ELEMENTAL_ORE.id) > 0) {
    return true;
  }
  await ensureMeleeWeapon(log);
  await freeSlotForOre(log);
  if (!await walkNear(ROCK_STAND2, 5, log)) {
    return false;
  }
  await settleScene();
  if (findOreOnGround()) {
    if (await takeElementalOre(log)) {
      return true;
    }
  }
  const beforeIdx = new Set(Npcs.query().name(EARTH_ELEMENTAL).within(20).results().map((n) => n.index));
  const rock = Locs.query().name("Pile of Rock").action("Mine").within(12).nearest();
  if (!rock) {
    log("no Pile of Rock to Mine in the west chamber");
    return false;
  }
  log("mining the elemental rock (Earth elemental will spawn)");
  if (!await rock.interact("Mine")) {
    return false;
  }
  let elemental = null;
  await Execution.delayUntil(() => {
    if (heldId(EW_ITEM.ELEMENTAL_ORE.id) > 0 || findOreOnGround()) {
      return true;
    }
    elemental = Npcs.query().name(EARTH_ELEMENTAL).where((n) => !beforeIdx.has(n.index) && !n.targetsAnotherPlayer()).within(16).nearest() ?? earthAtRock();
    return elemental !== null;
  }, 12000);
  if (heldId(EW_ITEM.ELEMENTAL_ORE.id) > 0) {
    return true;
  }
  if (await takeElementalOre(log)) {
    return true;
  }
  if (!elemental) {
    elemental = earthAtRock();
  }
  if (!elemental) {
    log("Earth elemental did not appear at the rock");
    return false;
  }
  log("killing the rock Earth elemental for Elemental ore");
  if (!await elemental.interact("Attack")) {
    return false;
  }
  await Execution.delayUntil(() => Game.inCombat() || !elemental.valid() || findOreOnGround() !== null, 6000);
  const deathTile = elemental.tile();
  const finished = await Execution.delayUntil(() => heldId(EW_ITEM.ELEMENTAL_ORE.id) > 0 || findOreOnGround() !== null || !elemental.valid(), 60000);
  if (!finished && Game.inCombat()) {
    log("Earth elemental combat did not finish in time");
    return false;
  }
  if (deathTile) {
    await walkNear(new Tile(deathTile.x, deathTile.z, deathTile.level), 1, log);
    await settleScene();
  }
  if (await takeElementalOre(log)) {
    return true;
  }
  log("Earth elemental died but Elemental ore was not on the ground");
  return false;
}
async function smeltElementalBar(log) {
  if (heldId(EW_ITEM.ELEMENTAL_METAL.id) > 0) {
    return true;
  }
  if (heldId(EW_ITEM.ELEMENTAL_ORE.id) === 0) {
    log("no Elemental ore to smelt");
    return false;
  }
  if (Inventory.countById(EW_ITEM.COAL.id) < COAL_NEED && Inventory.count(EW_ITEM.COAL.name) < COAL_NEED) {
    log(`need ${COAL_NEED} Coal to smelt Elemental ore`);
    return false;
  }
  const trySmelt = async () => {
    if (!await walkNear(FURNACE_STAND, 3, log)) {
      return "fail";
    }
    await settleScene();
    const before = heldId(EW_ITEM.ELEMENTAL_METAL.id);
    const mark = GameMessages.mark();
    log("placing Elemental ore and Coal into the Furnace");
    const ore = Inventory.items().find((i2) => i2.id === EW_ITEM.ELEMENTAL_ORE.id);
    const furnace = Locs.query().name("Furnace").within(10).nearest();
    if (!ore || !furnace) {
      return "fail";
    }
    if (!await ore.useOn(furnace)) {
      return "fail";
    }
    await Execution.delayUntil(() => heldId(EW_ITEM.ELEMENTAL_METAL.id) > before || GameMessages.sawSince(mark, FURNACE_COLD) || GameMessages.sawSince(mark, FURNACE_NEEDS_HEAT) || GameMessages.sawSince(mark, FURNACE_NEED_COAL), 1e4);
    if (heldId(EW_ITEM.ELEMENTAL_METAL.id) > before) {
      return "ok";
    }
    if (GameMessages.sawSince(mark, FURNACE_NEED_COAL)) {
      return "coal";
    }
    if (GameMessages.sawSince(mark, FURNACE_COLD)) {
      return "cold";
    }
    if (GameMessages.sawSince(mark, FURNACE_NEEDS_HEAT)) {
      return "hotter";
    }
    return "fail";
  };
  let result = await trySmelt();
  if (result === "ok") {
    return true;
  }
  if (result === "coal") {
    log("furnace refused — need 4 Coal in the pack");
    return false;
  }
  if (result === "cold") {
    log("furnace is cold — light it with lava first");
    return false;
  }
  if (result === "hotter" || result === "fail") {
    const air2 = await pullAirLever(log);
    if (air2 === "off") {
      log("air was on; re-pulling to restore blast");
      await pullAirLever(log);
    } else if (air2 === "nothing") {
      log("air lever did nothing — water wheel / bellows may not be ready");
      return false;
    }
    result = await trySmelt();
    return result === "ok";
  }
  return false;
}
async function smithElementalShield(log) {
  if (heldId(EW_ITEM.ELEMENTAL_SHIELD.id) > 0) {
    return true;
  }
  if (heldId(EW_ITEM.ELEMENTAL_METAL.id) === 0) {
    log("no Elemental metal to smith");
    return false;
  }
  if (heldId(EW_ITEM.BATTERED_BOOK.id) === 0) {
    log("need the Battered book as instructions on the workbench");
    return false;
  }
  if (heldId(EW_ITEM.HAMMER.id) === 0) {
    log("need a Hammer to work the metal");
    return false;
  }
  if (!await walkNear(WORKBENCH_STAND, 3, log)) {
    return false;
  }
  await settleScene();
  const before = heldId(EW_ITEM.ELEMENTAL_SHIELD.id);
  log("smithing an Elemental shield on the Workbench");
  return useOnLoc(EW_ITEM.ELEMENTAL_METAL.id, { name: "Workbench", near: WORKBENCH_STAND, within: 10 }, [], () => heldId(EW_ITEM.ELEMENTAL_SHIELD.id) > before, log);
}

// src/bot/api/ai/quests/defs/elementalworkshop/index.ts
function custom5(name, run2) {
  return { kind: "custom", name, run: run2 };
}
function needSmeltMaterials(snap) {
  return held15(snap, EW_ITEM.ELEMENTAL_METAL.id) === 0 && held15(snap, EW_ITEM.ELEMENTAL_SHIELD.id) === 0;
}
function needBellowsWork(snap) {
  return !hasFlag(snap.progress, EW_FLAG.BELLOWS);
}
function needWaterWork(snap) {
  return !hasFlag(snap.progress, EW_FLAG.WATER);
}
function needFurnaceWork(snap) {
  return !hasFlag(snap.progress, EW_FLAG.FURNACE);
}
function sourceKnife2(snap) {
  if (held15(snap, EW_ITEM.BATTERED_KEY.id) > 0 || hasHeldSlashTool(snap)) {
    return null;
  }
  const bankWeapon2 = bestBankWeapon(snap);
  return fromBank2(snap, EW_ITEM.KNIFE, 1) ?? (bankWeapon2 ? fromBank2(snap, bankWeapon2, 1) : null) ?? { kind: "grabGround", item: EW_ITEM.KNIFE.name, anchor: KNIFE_SPAWN2, waitIfMissing: true };
}
function decide30(snap) {
  if (snap.journal === "complete") {
    return { kind: "done" };
  }
  if (snap.journal === "unknown") {
    return { kind: "wait", reason: "quest journal not loaded" };
  }
  const stage = snap.progress?.stage ?? snap.stage;
  if (stage === undefined) {
    return { kind: "wait", reason: "Elemental Workshop stage unavailable" };
  }
  if (stage === EW_STAGE.COMPLETE) {
    return { kind: "done" };
  }
  const area = ewArea(snap.tile);
  if (stage === EW_STAGE.NOT_STARTED) {
    if (held15(snap, EW_ITEM.BATTERED_BOOK.id) === 0) {
      if (area === "workshop") {
        return custom5("leave workshop for the bookcase", leaveWorkshop);
      }
      return fromBank2(snap, EW_ITEM.BATTERED_BOOK, 1) ?? custom5("search Seers bookcase for the Battered book", searchBookcase);
    }
    return custom5("read the Battered book", readBatteredBook);
  }
  if (held15(snap, EW_ITEM.BATTERED_KEY.id) === 0 && stage < EW_STAGE.ENTERED) {
    if (held15(snap, EW_ITEM.BATTERED_BOOK.id) === 0) {
      return fromBank2(snap, EW_ITEM.BATTERED_BOOK, 1) ?? custom5("search Seers bookcase for the Battered book", searchBookcase);
    }
    const knife = sourceKnife2(snap);
    if (knife) {
      return knife;
    }
    return custom5("slash the Battered book for the key", slashBookForKey);
  }
  if (held15(snap, EW_ITEM.ELEMENTAL_SHIELD.id) > 0) {
    return { kind: "wait", reason: "waiting for Elemental Workshop quest complete" };
  }
  if (held15(snap, EW_ITEM.ELEMENTAL_METAL.id) > 0) {
    if (area !== "workshop") {
      if (held15(snap, EW_ITEM.BATTERED_BOOK.id) === 0 || held15(snap, EW_ITEM.HAMMER.id) === 0) {
        const load = surfaceLoadout(snap, false, false);
        if (load) {
          return load;
        }
      }
      return custom5("re-enter the workshop to smith the shield", enterWorkshop);
    }
    if (held15(snap, EW_ITEM.BATTERED_BOOK.id) === 0) {
      return custom5("leave workshop for the Battered book", leaveWorkshop);
    }
    if (held15(snap, EW_ITEM.HAMMER.id) === 0) {
      return custom5("leave workshop for a Hammer", leaveWorkshop);
    }
    return custom5("smith the Elemental shield", smithElementalShield);
  }
  if (area !== "workshop") {
    if (held15(snap, EW_ITEM.BATTERED_KEY.id) === 0) {
      const bankKey = fromBank2(snap, EW_ITEM.BATTERED_KEY, 1);
      if (bankKey) {
        return bankKey;
      }
      if (stage < EW_STAGE.ENTERED) {
        return { kind: "wait", reason: "need the Battered key to open the smithy wall" };
      }
    }
    const bellows = stage < EW_STAGE.ENTERED || needBellowsWork(snap);
    const smelt = stage < EW_STAGE.ENTERED || needSmeltMaterials(snap);
    const load = surfaceLoadout(snap, bellows, smelt);
    if (load) {
      return load;
    }
    if (!hasPickaxe(snap) && needSmeltMaterials(snap)) {
      return { kind: "wait", reason: "need a pickaxe before entering the Elemental Workshop" };
    }
    return custom5("enter the Elemental Workshop", enterWorkshop);
  }
  if (needWaterWork(snap)) {
    return custom5("start the water wheel", startWaterWheel);
  }
  if (needBellowsWork(snap)) {
    const needLeather = held15(snap, EW_ITEM.LEATHER.id) === 0;
    const needNeedle = held15(snap, EW_ITEM.NEEDLE.id) === 0;
    if (needLeather || needNeedle) {
      return custom5("search crates for leather/needle", (log) => searchCratesFor({ bowl: false, leather: needLeather, needle: needNeedle }, log));
    }
    if (held15(snap, EW_ITEM.THREAD.id) === 0) {
      return custom5("leave workshop for Thread", leaveWorkshop);
    }
    return custom5("fix the bellows", fixBellows);
  }
  if (needFurnaceWork(snap)) {
    if (held15(snap, EW_ITEM.STONE_BOWL.id) === 0 && held15(snap, EW_ITEM.STONE_BOWL_FULL.id) === 0) {
      return custom5("search crates for a stone bowl", (log) => searchCratesFor({ bowl: true, leather: false, needle: false }, log));
    }
    return custom5("light the furnace with lava", lightFurnace);
  }
  if (held15(snap, EW_ITEM.ELEMENTAL_ORE.id) === 0) {
    if (!hasPickaxe(snap) && !bestHeldPickaxe(snap)) {
      return custom5("leave workshop for a pickaxe", leaveWorkshop);
    }
    return custom5("mine Elemental ore from the Earth elemental", mineElementalOre);
  }
  if (held15(snap, EW_ITEM.COAL.id) < COAL_NEED) {
    return custom5("leave workshop for Coal", leaveWorkshop);
  }
  return custom5("smelt Elemental metal at the furnace", smeltElementalBar);
}
var elementalworkshop = {
  record: QUESTS.find((r) => r.id === "elemental_workshop"),
  bank: SEERS_BANK,
  ownsInventory: true,
  tools: ["knife", "hammer", "needle", "thread", "leather", "coal", "battered book", "battered key"],
  readProgress: readElementalWorkshopProgress,
  sustain: { foods: ["Swordfish", "Lobster", "Salmon", "Trout"], eatBelowHp: 0.45 },
  warnReadiness: warnElementalWorkshopReadiness,
  decide: decide30
};

