var MAX_ROUNDS = 25;
function nextStake(purse, pack) {
  return Math.min(MAX_BET, pack, purse + 1);
}
function purseAfter(purse, stake, result) {
  return result === "loss" ? purse + stake : Math.min(MAX_BET, purse * 2 + 1);
}
