async function leaveMaze(log) {
  const here3 = Game.tile();
  if (!here3 || !inMaze(here3)) {
    return true;
  }
  if (here3.z >= 9000) {
    if (!await walk2(new Tile(2938, 9657, 0), log, 0) || !await mazeSceneLoaded()) {
      return false;
    }
    const ladder = locAt2("Ladder", new Tile(2939, 9657, 0));
    if (!ladder) {
      log("no cellar ladder out of the basement");
      return false;
    }
    log("climbing out of the cellar");
    if (!await ladder.interact("Climb-up")) {
      return false;
    }
    return Execution.delayUntil(() => (Game.tile()?.z ?? 9999) < 9000, 8000);
  }
  if (here3.z > 3251 && here3.x > 2937) {
    if (!await walk2(new Tile(2938, 3252, 0), log, 0) || !await mazeSceneLoaded()) {
      return false;
    }
    const door2 = locAt2("Door", new Tile(2938, 3252, 0));
    if (!door2) {
      log("no exit door in the scene");
      return false;
    }
    log("opening the one-way exit door");
    if (!await door2.interact("Open")) {
      return false;
    }
    return Execution.delayUntil(() => (Game.tile()?.x ?? 9999) <= 2937, 8000);
  }
  const front = MAZE_LEGS[0];
  if (front.kind !== "door") {
    return false;
  }
  if (!await walk2(front.land, log, 0) || !await mazeSceneLoaded()) {
    return false;
  }
  const key = Inventory.items().find((i2) => i2.id === DS_ID.MAZE_KEY);
  const door = locAt2("Door", front.door);
  if (!key || !door) {
    log("cannot re-open the front door from the inside");
    return false;
  }
  log("letting myself back out of the front door");
  if (!await key.useOn(door)) {
    return false;
  }
  return Execution.delayUntil(() => !inMaze(Game.tile()), 8000);
}

class MazeRun {
  index = -1;
  async step(log) {
    if (heldById2(DS_ID.MAP_MELZAR)) {
      return true;
    }
    const here3 = Game.tile();
    if (!here3) {
      return false;
    }
    const keyLeg = MAZE_LEGS.findIndex((l) => l.kind === "door" && l.keyId !== DS_ID.MAZE_KEY && heldById2(l.keyId));
    if (keyLeg >= 0) {
      this.index = keyLeg;
    } else if (this.index < 0) {
      this.index = legFromPosition(here3);
      log(`picking the maze up at leg ${this.index}`);
    }
    while (this.index < MAZE_LEGS.length && legDone(MAZE_LEGS[this.index], here3)) {
      this.index++;
    }
    if (this.index >= MAZE_LEGS.length) {
      return heldById2(DS_ID.MAP_MELZAR);
    }
    const leg = MAZE_LEGS[this.index];
    switch (leg.kind) {
      case "kill":
        return killFor(leg, log);
      case "door":
        return openDoor(leg, log);
      case "climb":
        return climb3(leg, log);
      case "chest":
        if (!await walk2(leg.stand, log, 1) || !await mazeSceneLoaded()) {
          return false;
        }
        return lootChest(DS_ID.MAP_MELZAR, log);
    }
  }
  static keyIds() {
    return KEY_IDS;
  }
}

