var MINE_TIMEOUT_MS = 20000;
async function mineFor(rockIds, item2, want, at2, log) {
  if (Inventory.count(item2) >= want) {
    return true;
  }
  if (!Inventory.items().some((i2) => i2.name?.toLowerCase().includes("pickaxe"))) {
    log("no pickaxe in the pack");
    return false;
  }
  if (Inventory.isFull()) {
    log(`pack is full — no room for ${item2}`);
    return false;
  }
  const ids = new Set(rockIds);
  const rock = () => Locs.query().where((l) => ids.has(l.id)).action("Mine").within(14).nearest();
  const seam = () => Locs.query().where((l) => ids.has(l.id)).action("Mine").within(14).count();
  if (!rock()) {
    log(`no live ${item2} rock within 14 — walking to the seam at (${at2.x},${at2.z})`);
    if (!await walk3(at2, log, 2) || !await sceneLoaded()) {
      log(`could not reach the ${item2} seam at (${at2.x},${at2.z})`);
      return false;
    }
  }
  const target = rock();
  if (!target) {
    log(`no ${item2} rocks in reach — waiting on a respawn (mining ${Skills.level("mining")}, ` + `${Inventory.count(item2)}/${want} ${item2} held)`);
    await Execution.delayTicks(5);
    return false;
  }
  const before = Inventory.count(item2);
  const spot = target.tile();
  log(`mining ${item2} ${before}/${want} — rock ${target.id} at (${spot.x},${spot.z}) ` + `${target.distance()} tile(s) away, ${seam()} live rock(s) in the seam, ${Inventory.free()} free slot(s)`);
  if (!await target.interact("Mine")) {
    log(`the Mine click on rock ${target.id} was not accepted`);
    return false;
  }
  const swungAt = Date.now();
  const landed = await Execution.delayUntil(() => Inventory.count(item2) > before, MINE_TIMEOUT_MS);
  const took = ((Date.now() - swungAt) / 1000).toFixed(1);
  if (!landed) {
    log(`gave up on rock ${target.id} after ${took}s with no ${item2} — mining ${Skills.level("mining")}; ` + "the next pass re-clicks and restarts the swing, so a rock slower than " + `${MINE_TIMEOUT_MS / 1000}s never finishes`);
    return false;
  }
  const now = Inventory.count(item2);
  log(`got ${item2} ${now}/${want} in ${took}s`);
  return now >= want;
}
