var custom8 = (name, run2) => ({ kind: "custom", name, run: run2 });
var SHOPPING_KEEP = [
  "coins",
  "maze key",
  "pickaxe",
  "hammer",
  "lobster pot",
  "wizard's mind bomb",
  "unfired bowl",
  "silk",
  "plank",
  "jug",
  "clay"
];
function makeRoom(snap, slots = 1) {
  if (snap.freeSlots === undefined || snap.freeSlots >= slots) {
    return null;
  }
  const food = QuestFood.name?.toLowerCase();
  const keep = food ? [...SHOPPING_KEEP, food] : [...SHOPPING_KEEP];
  const spare = [...snap.inv.keys()].some((name) => !keep.some((k) => name.includes(k)));
  return spare ? { kind: "deposit", keep } : { kind: "wait", reason: `no room for ${slots} more item${slots === 1 ? "" : "s"} and nothing spare to bank` };
}
