  hammer: (snap) => makeRoom(snap) ?? buy2("Hammer", 1, SUPPLY.GENERAL_STORE, 100),
  silk: (snap) => makeRoom(snap) ?? buy2("Silk", 1, SUPPLY.THESSALIA, 200),
  "lobster pot": (snap) => makeRoom(snap) ?? buy2("Lobster pot", 1, SUPPLY.GERRANT, 200),
  "wizard's mind bomb": (snap) => makeRoom(snap) ?? custom8("buy a mind bomb at the Rising Sun", buyMindBomb),
  "unfired bowl": (snap) => makeRoom(snap) ?? custom8("make an unfired bowl", makeUnfiredBowl),
