    return FC_STAGE.SPOKEN_GEM_TRADER;
  if (text.includes("is on a treasure hunt in the"))
    return FC_STAGE.CALEB_WHERE;
  if (text.includes("crest piece, i need to find the other"))
    return FC_STAGE.CALEB_PIECE;
  if (text.includes("will let me have his piece in return for"))
    return FC_STAGE.SPOKEN_CALEB;
  if (text.includes("i need to find his son"))
    return FC_STAGE.SPOKEN_DIMINTHEIS;
  if (text.includes("i can start this quest"))
    return FC_STAGE.NOT_STARTED;
