async function readFamilyCrestProgress() {
  const status = Quests.status(FC_QUEST);
  if (status === "complete")
    return { stage: FC_STAGE.COMPLETE, flags: new Set };
  if (status === "notStarted")
    return { stage: FC_STAGE.NOT_STARTED, flags: new Set };
  if (status !== "inProgress")
    return;
  const lines = await Quests.journal(FC_QUEST);
  const progress = parseFamilyCrestJournal(lines);
  if (reader.modals().main !== -1) {
    actions.closeModal();
    await Execution.delayTicks(1);
  }
  journalRead2.reads++;
  journalRead2.cached = progress === undefined;
  if (progress) {
    lastGood7 = progress;
  } else {
    journalRead2.failures++;
  }
  const used = progress ?? lastGood7;
  journalRead2.stage = used?.stage;
  return used;
}

