function barcrawlFunds(snap) {
  if ((snap.invIds?.get(HD_ID.COINS) ?? 0) >= BARCRAWL_GP) {
    return null;
  }
  if (!snap.bankKnown) {
    return { kind: "scanBank" };
  }
  return {
    kind: "withdraw",
    items: [{ name: HD_ITEM.COINS, qty: BARCRAWL_GP * 4, id: HD_ID.COINS }]
  };
}

