    return HD_STAGE.DEFEATED_DAGJR;
  if (text.includes("i found jossik in an underground cavern"))
    return HD_STAGE.DEFEATED_DAGJR;
  if (text.includes("i must search this place"))
    return HD_STAGE.REPAIRED_LIGHTHOUSE;
  if (text.includes("i managed to repair the lighthouse light"))
    return HD_STAGE.REPAIRED_LIGHTHOUSE;
  if (text.includes("now i need to find some way of"))
    return HD_STAGE.ENTERED_LIGHTHOUSE;
  if (text.includes("i repaired the bridge leading to rellekka and got a key"))
    return HD_STAGE.ENTERED_LIGHTHOUSE;
  if (text.includes("larrissa is very worried about her boyfriend"))
    return HD_STAGE.STARTED;
