// src/bot/api/ai/quests/defs/fightarena/fights.ts
var FA_FIGHT = {
  ogre: { what: "Khazard Ogre", npcId: FA_NPC.OGRE, guard: 600 },
  scorpion: { what: "Khazard Scorpion", npcId: FA_NPC.SCORPION, guard: 600 },
  bouncer: { what: "Bouncer", npcId: FA_NPC.BOUNCER, guard: 1500 }
};
var PROTECT_MELEE = "protect from melee";
var PROTECT_LEVEL2 = 43;
var EAT_AT_MISSING3 = 15;
var SEARCH_RADIUS2 = 20;
var MISSING_TO_WIN = 3;
function fightWon(swings, missingTicks) {
  return swings > 0 && missingTicks >= MISSING_TO_WIN;
}
var ENGAGE_PROOF = 12;
function unengaged(swings, everEngaged) {
  return !everEngaged && swings >= ENGAGE_PROOF;
}
function hungry3() {
  const max2 = Skills.level("hitpoints");
  return max2 > 0 && Skills.effective("hitpoints") <= max2 - EAT_AT_MISSING3;
}
function target(npcId) {
  return Npcs.query().where((n) => n.id === npcId).action("Attack").where((n) => !n.targetsAnotherPlayer()).within(SEARCH_RADIUS2).nearest();
}
async function drainWinDialogue() {
  for (let i2 = 0;i2 < 30; i2++) {
    if (ChatDialog.canContinue()) {
      await ChatDialog.continue();
      await Execution.delayTicks(1);
      continue;
    }
    if (!ChatDialog.isOpen()) {
      return;
    }
    await Execution.delayTicks(1);
  }
}
async function dropPrayer() {
  if (Prayer.active(PROTECT_MELEE)) {
    await Prayer.set(PROTECT_MELEE, false);
  }
}
async function runFight2(fight2, log) {
  const canPray = Skills.level("prayer") >= PROTECT_LEVEL2;
  if (!canPray) {
    log(`prayer below ${PROTECT_LEVEL2} — ${fight2.what} will land hits this fight`);
  }
  Game.setAutoRetaliate(true);
  let lastTick2 = -1;
  let reported = -1;
  let swings = 0;
  let attacking = -1;
  let missing = 0;
  let everEngaged = false;
  try {
    for (let i2 = 0;i2 < fight2.guard; i2++) {
      if (EventSignal.pending()) {
        log(`${fight2.what}: yielding to a random event`);
        return "stuck";
      }
      const now = Game.tick();
      if (now === lastTick2) {
        await Execution.delayTicks(1);
        continue;
      }
      lastTick2 = now;
      if (ChatDialog.isOpen() || ChatDialog.canContinue()) {
        await drainWinDialogue();
        continue;
      }
      if (canPray && Prayer.points() > 0 && !Prayer.active(PROTECT_MELEE)) {
        await Prayer.set(PROTECT_MELEE, true);
        continue;
      }
      if (hungry3()) {
        await Sustain.run();
        continue;
      }
      const npc = target(fight2.npcId);
      if (!npc) {
        attacking = -1;
        missing++;
        if (fightWon(swings, missing)) {
          log(`${fight2.what}: down after ${swings} attacks`);
          await drainWinDialogue();
          await dropPrayer();
          return "won";
        }
        await Execution.delayTicks(1);
        continue;
      }
      missing = 0;
      everEngaged = everEngaged || Game.inCombat();
      if (unengaged(swings, everEngaged)) {
        log(`${fight2.what}: ${swings} attacks and never in combat at (${npc.tile().x},${npc.tile().z}) — still caged`);
        return "unengaged";
      }
      if (now - reported >= 40) {
        reported = now;
        log(`${fight2.what}: hp=${Skills.effective("hitpoints")}/${Skills.level("hitpoints")}` + ` prayer=${Prayer.points()} attacks=${swings} at (${npc.tile().x},${npc.tile().z})`);
      }
      if (npc.index === attacking && Game.inCombat()) {
        await Execution.delayTicks(1);
        continue;
      }
      if (await npc.interact("Attack")) {
        attacking = npc.index;
        swings++;
      }
      await Execution.delayTicks(1);
    }
    log(`${fight2.what}: gave up after ${fight2.guard} ticks (${swings} attacks)`);
    return "stuck";
  } finally {
    if (!Game.inCombat()) {
      await dropPrayer();
    }
  }
}

// src/bot/api/ai/quests/defs/fightarena/journal.ts
var FIGHT_ARENA_QUEST = "Fight Arena";
var FA_STAGE = {
  NOT_STARTED: 0,
  STARTED: 1,
  OBTAINED_ARMOUR: 2,
  SPOKEN_DRUNKGUARD: 3,
  GIVEN_KHALI_BREW: 5,
  ENTERED_OGRE_FIGHT: 6,
  DEFEATED_OGRE: 8,
  SENT_JAIL: 9,
  DEFEATED_SCORPION: 10,
  DEFEATED_BOUNCER: 11,
  FREED_SERVILS: 12,
  DEFEATED_KHAZARD: 13,
  COMPLETE: 14
};
function normalizeJournal3(lines) {
  return (typeof lines === "string" ? lines : lines.join(" ")).replace(/@[a-z0-9]{3}@/gi, " ").replace(/[|\s]+/g, " ").trim().toLowerCase();
}
var NEEDLES = [
  ["quest complete!", FA_STAGE.COMPLETE],
  ["i eventually killed", FA_STAGE.DEFEATED_KHAZARD],
  ["challenged me to fight him, but i ran away", FA_STAGE.FREED_SERVILS],
  ["wants to kill me himself", FA_STAGE.DEFEATED_BOUNCER],
  ["ordered me to fight his pet", FA_STAGE.DEFEATED_SCORPION],
  ["going to have to fight in the arena", FA_STAGE.SENT_JAIL],
  ["should talk to jeremy in the fight arena", FA_STAGE.DEFEATED_OGRE],
  ["i need to protect jeremy and his father", FA_STAGE.ENTERED_OGRE_FIGHT],
  ["now i've got the keys", FA_STAGE.GIVEN_KHALI_BREW],
  ["guards told me that he really likes", FA_STAGE.SPOKEN_DRUNKGUARD],
  ["luckily i found some khazard armour in a chest", FA_STAGE.OBTAINED_ARMOUR],
  ["and try to find her family", FA_STAGE.STARTED],
  ["i can start this quest by speaking to", FA_STAGE.NOT_STARTED]
];
function parseFightArenaJournal(lines) {
  const text = normalizeJournal3(lines);
  if (text.length === 0) {
    return;
  }
  return NEEDLES.find(([needle]) => text.includes(needle))?.[1];
}
var lastRead;
async function readFightArenaStage() {
  const status = Quests.status(FIGHT_ARENA_QUEST);
  if (status === "complete") {
    lastRead = FA_STAGE.COMPLETE;
    return FA_STAGE.COMPLETE;
  }
  if (status === "notStarted") {
    lastRead = FA_STAGE.NOT_STARTED;
    return FA_STAGE.NOT_STARTED;
  }
  if (status !== "inProgress") {
    return lastRead;
  }
  const stage = parseFightArenaJournal(await Quests.journal(FIGHT_ARENA_QUEST));
  if (reader.modals().main !== -1) {
    actions.closeModal();
    await Execution.delayTicks(1);
  }
  if (stage !== undefined) {
    lastRead = stage;
    return stage;
  }
  return lastRead;
}

