var CONTINUE_LABEL = "Click here to continue";
async function clearBox() {
  if (reader.modals().main === -1) {
    return false;
  }
  const cont = reader.mainModalButtonNearText(CONTINUE_LABEL);
  if (cont > 0 && !actions.menuAction(997 /* PAUSE_BUTTON */, 0, 0, cont)) {
    actions.ifButton(cont);
  } else if (cont <= 0) {
    actions.closeModal();
  }
  await Execution.delayTicks(1);
  return true;
}
function boxText() {
  return reader.mainModalTexts().join(" ").replace(/\s+/g, " ").trim().toLowerCase();
}
var QUIET_POLLS = 6;
async function driveBoxes2(drive, log) {
  const deadline = performance.now() + (drive.ms ?? 30000);
  const done = drive.expect ?? (() => false);
  const spent = new Set;
  const available = () => (drive.prefer ?? []).filter((p) => !spent.has(p));
  let spoken = [];
  let acted = false;
  let quiet = 0;
  while (performance.now() < deadline) {
    if (done()) {
      return true;
    }
    if (EventSignal.pending()) {
      return done();
    }
    const opts = ChatDialog.options();
    if (opts.length === 0 && ChatDialog.isOpen()) {
      const texts = ChatDialog.texts();
      if (texts.length > 0) {
        spoken = texts;
      }
    }
    if (opts.length > 0) {
      const pick = pickByLine(spoken, opts, drive.rules ?? []) ?? pickPreferred(opts, available());
      if (!pick) {
        if (drive.strict !== false) {
          log(`no rule or preference matched [${opts.join(" | ")}] after "${spoken.join(" ")}"`);
          return done();
        }
        await ChatDialog.chooseOption(opts[opts.length - 1]);
      } else {
        const oneShot = (drive.once ?? []).find((p) => pick.toLowerCase().includes(p.toLowerCase()));
        if (oneShot !== undefined) {
          spent.add(oneShot);
        }
        await ChatDialog.chooseOption(pick);
      }
      spoken = [];
      acted = true;
      quiet = 0;
      await Execution.delayTicks(2);
      continue;
    }
    if (ChatDialog.canContinue()) {
      await ChatDialog.continue();
      acted = true;
      quiet = 0;
      await Execution.delayTicks(1);
      continue;
    }
    if (await clearBox()) {
      acted = true;
      quiet = 0;
      continue;
    }
    if (acted && ++quiet >= QUIET_POLLS) {
      return drive.expect ? done() : true;
    }
    await Execution.delayTicks(1);
  }
  return drive.expect ? done() : acted;
}
async function talkBoxes(npc, drive, log) {
  if (drive.expect?.()) {
    return true;
  }
  await clearBox();
  if (!await openDialogue(npc, log)) {
    return false;
  }
  return driveBoxes2(drive, log);
}

