var FC_STAGE2 = {
  NOT_STARTED: 0,
  STARTED: 1,
  IN_COMP: 2,
  GARLIC_COMP: 3,
  WON_COMP: 4,
  COMPLETE: 5
};
function normalize25(lines) {
  return (typeof lines === "string" ? lines : lines.join(" ")).replace(/@[a-z0-9]{3}@/gi, " ").replace(/[|\s]+/g, " ").trim().toLowerCase();
}
var STAGES4 = [
  ["quest complete!", FC_STAGE2.COMPLETE],
  ["i easily won the contest", FC_STAGE2.WON_COMP],
  ["next to the pipes", FC_STAGE2.GARLIC_COMP],
  ["next to the willow tree", FC_STAGE2.IN_COMP],
  ["fishing contest pass", FC_STAGE2.STARTED],
  ["i can start this quest by speaking to", FC_STAGE2.NOT_STARTED]
];
function parseFishingContestJournal(lines) {
  const text = normalize25(lines);
  if (text.length === 0) {
    return;
  }
  return STAGES4.find(([needle]) => text.includes(needle))?.[1];
}
async function readFishingContestStage() {
  const status = Quests.status(FC_NAME);
  if (status === "complete") {
    return FC_STAGE2.COMPLETE;
  }
  if (status === "notStarted") {
    return FC_STAGE2.NOT_STARTED;
  }
  if (status !== "inProgress") {
    return;
  }
  const stage = parseFishingContestJournal(await Quests.journal(FC_NAME));
  if (reader.modals().main !== -1) {
    actions.closeModal();
    await Execution.delayTicks(1);
  }
  return stage;
}

