// src/bot/api/ai/quests/defs/sheepherder/index.ts
var SUIT_GP = 100;
var custom23 = (name, run2) => ({ kind: "custom", name, run: run2 });
var held35 = (snap, id) => snap.invIds?.get(id) ?? 0;
var wearing2 = (snap, id) => snap.wornIds?.has(id) ?? false;
function dressed(snap) {
  for (const [id, name] of [[JACKET_OBJ, JACKET], [TROUSERS_OBJ, TROUSERS]]) {
    if (wearing2(snap, id)) {
      continue;
    }
    return held35(snap, id) > 0 ? { kind: "equip", item: name } : { kind: "talk", stop: ORBON };
  }
  return null;
}
function armed(snap) {
  if (wearing2(snap, PROD_OBJ)) {
    return null;
  }
  return custom23(`fetch the ${PROD} from the barn`, (log) => fetchProd(log));
}
function nextSheep(snap) {
  return SHEEP.find((n) => !hasFlag(snap.progress, `burnt-${n}`)) ?? null;
}
function decide56(snap) {
  if (snap.journal === "complete") {
    return { kind: "done" };
  }
  if (snap.journal === "unknown") {
    return { kind: "wait", reason: "quest journal not loaded" };
  }
  if (snap.journal === "notStarted") {
    return { kind: "talk", stop: HALGRIVE };
  }
  const stage = snap.progress?.stage;
  if (stage === undefined) {
    return { kind: "wait", reason: "Sheep Herder journal stage unavailable" };
  }
  if (stage === SH_STAGE.COMPLETE) {
    return { kind: "done" };
  }
  if (stage === SH_STAGE.NOT_STARTED) {
    return { kind: "talk", stop: HALGRIVE };
  }
  if (stage === SH_STAGE.NEED_SUIT) {
    return (snap.inv.get("coins") ?? 0) >= SUIT_GP ? { kind: "talk", stop: ORBON } : { kind: "withdraw", items: [{ name: "Coins", qty: SUIT_GP * 10 }], bank: BANK5 };
  }
  const n = nextSheep(snap);
  if (n === null) {
    return { kind: "talk", stop: HALGRIVE };
  }
  const suit = dressed(snap);
  if (suit) {
    return suit;
  }
  if (held35(snap, BONES_OBJ[n]) > 0) {
    return custom23(`incinerate the remains of sheep ${n}`, (log) => incinerate(n, log));
  }
  const prod = armed(snap);
  if (prod) {
    return prod;
  }
  if (held35(snap, FEED_OBJ) === 0) {
    return { kind: "talk", stop: HALGRIVE };
  }
  return custom23(`herd and kill sheep ${n}`, (log) => penAndKill(n, log));
}
var sheepherder = {
  record: QUESTS.find((record) => record.id === "sheepherder"),
  bank: BANK5,
  food: 4,
  tools: ["coins", PROD.toLowerCase(), FEED.toLowerCase(), JACKET.toLowerCase(), TROUSERS.toLowerCase(), "bones"],
  readProgress: readSheepHerderProgress,
  decide: decide56
};

