var RANGED_SLOTS = [
  ["Coif", "Leather cowl"],
  ["Dragonhide body", "Studded body", "Hardleather body", "Leather body"],
  ["Dragonhide chaps", "Studded chaps", "Leather chaps"],
  ["Dragon vambraces", "Leather vambraces", "Leather gloves"]
];
var MELEE_TIERS = ["Rune", "Adamant", "Mithril", "Black", "Steel", "Iron", "Bronze"];
var MELEE_KINDS = ["scimitar", "longsword", "sword", "battleaxe", "mace", "warhammer"];
var MELEE_WEAPONS2 = MELEE_TIERS.flatMap((tier) => MELEE_KINDS.map((kind) => `${tier} ${kind}`));
var RANGED_ARMOUR_NAMES = RANGED_SLOTS.flat().map((name) => name.toLowerCase());
var IKOV_GEAR_NAMES = [...RANGED_ARMOUR_NAMES, ...MELEE_WEAPONS2.map((name) => name.toLowerCase())];
var refused = new Set;
function stocked(snap, name) {
  const key2 = name.toLowerCase();
  return (snap.inv.get(key2) ?? 0) + (snap.bank?.get(key2) ?? 0);
}
function dressed2(snap, slot) {
  return slot.some((name) => snap.worn.has(name.toLowerCase()));
}
function bestInBank2(snap, slot) {
  return slot.find((name) => !refused.has(name.toLowerCase()) && stocked(snap, name) > 0) ?? null;
}
function rangedGearWanted(snap) {
  const out = [];
  for (const slot of RANGED_SLOTS) {
    if (dressed2(snap, slot)) {
      continue;
    }
    const pick = bestInBank2(snap, slot);
    if (pick) {
      out.push(pick);
    }
  }
  return out;
}
function rangedArmourStep(snap) {
  if (!snap.bankKnown) {
    return null;
  }
  const wanted = rangedGearWanted(snap);
  if (wanted.length === 0) {
    return null;
  }
  const missing = wanted.filter((name) => (snap.inv.get(name.toLowerCase()) ?? 0) === 0);
  if (missing.length > 0) {
    return { kind: "withdraw", items: missing.map((name) => ({ name, qty: 1 })) };
  }
  return {
    kind: "custom",
    name: `wear ${wanted.join(", ")}`,
    run: async (log) => {
      for (const name of wanted) {
        if (Equipment.contains(name) || await Equipment.equip(name)) {
          continue;
        }
        log(`ikov: the server refused ${name} — a level or quest gate; dropping it from the kit`);
        refused.add(name.toLowerCase());
      }
      return true;
    }
  };
}
function bestMeleeWeapon(snap) {
  if (!snap.bankKnown) {
    return null;
  }
  return bestInBank2(snap, MELEE_WEAPONS2);
}
function meleeWeaponStep(snap) {
  const want = bestMeleeWeapon(snap);
  if (!want || snap.worn.has(want.toLowerCase())) {
    return null;
  }
  if ((snap.inv.get(want.toLowerCase()) ?? 0) === 0) {
    return { kind: "withdraw", items: [{ name: want, qty: 1 }] };
  }
  return {
    kind: "custom",
    name: `wield ${want}`,
    run: async (log) => {
      if (Equipment.contains(want) || await Equipment.equip(want)) {
        return true;
      }
      log(`ikov: the server refused ${want} — an attack-level gate; dropping it from the kit`);
      refused.add(want.toLowerCase());
      return true;
    }
  };
}

