function upassArea(tile) {
  if (!tile) {
    return "unknown";
  }
  const { x: x2, z, level: level2 } = tile;
  if (level2 === 1 && x2 >= 2112 && x2 <= 2175) {
    if (z >= 4672 && z <= 4735)
      return "main";
    if (z >= 4608 && z <= 4671)
      return "temple";
    if (z >= 4544 && z <= 4607)
      return "witch";
  }
  if (level2 === 1 && x2 >= 1984 && x2 <= 2047 && z >= 4672 && z <= 4735) {
    return "voyage";
  }
  if (x2 >= 2304 && x2 <= 2367) {
    if (z >= 9856 && z <= 9919)
      return "kalrag";
    if (z >= 9792 && z <= 9855)
      return "dwarves";
  }
  if (z >= 9536 && z <= 9599)
    return "gridpit";
  if (z >= 9600 && z <= 9663)
    return "area2";
  if (z >= 9664 && z <= 9727)
    return "area1";
  if (z >= 5000) {
    return "unknown";
  }
  return level2 === 0 && x2 >= 2433 && x2 <= 2556 && z >= 3266 && z <= 3334 ? "westardougne" : "mainland";
}
