async function crossOnce(dest, log) {
  const me = here7();
  if (!me) {
    return "nowhere";
  }
  if (me.level !== TABLE_LEVEL || dest.level !== TABLE_LEVEL) {
    return "nowhere";
  }
  const from = await areaAt(me);
  if (from === null) {
    log(`pass: (${me.x},${me.z}) is not on the walkable graph — stepping back onto it`);
    for (const area3 of UPASS_AREAS) {
      if (await Traversal.walkResilient(area3.anchor, { radius: 2, attempts: 1, timeoutMs: 15000 })) {
        return "crossed";
      }
    }
    return "nowhere";
  }
  const goal = await areaAt(dest);
  if (goal === null) {
    log(`pass: (${dest.x},${dest.z}) is in no area the route knows`);
    return "nowhere";
  }
  if (from === goal) {
    return "nowhere";
  }
  const edge = chainFrom(from, goal);
  if (!edge) {
    log(`pass: no chain of crossings from ${from} to ${goal}`);
    return "nowhere";
  }
  log(`pass: in ${from}, heading for ${goal} — ${edge.op} ${edge.loc} from (${edge.stand.x},${edge.stand.z}), lands (${edge.lands.x},${edge.lands.z}) in ${edge.to}`);
  if (!await Traversal.walkResilient(edge.stand, { radius: 0, attempts: 1, timeoutMs: 20000 })) {
    log(`pass: could not stand on (${edge.stand.x},${edge.stand.z})`);
    return "same";
  }
  const mark = GameMessages.mark();
  if (!await operate(edge, log)) {
    return "same";
  }
  await Execution.delayUntil(() => verdictSince(mark) !== null, QUIET_MS);
  const said = verdictSince(mark);
  if (said === "refused" || said === "failed") {
    log(`pass: ${edge.op} ${edge.loc} ${said} — ${GameMessages.since(mark).map((m) => m.text).slice(-2).join(" / ")}`);
    return "same";
  }
  await Execution.delayUntil(() => {
    const t = here7();
    return t !== null && t.x === edge.lands.x && t.z === edge.lands.z && t.level === edge.lands.level;
  }, said === "crossing" ? CROSS_MS2 : QUIET_MS);
  await settleScene();
  const now = here7() ?? me;
  const landed = await areaAt(now);
  if (landed === edge.to) {
    log(`pass: ${edge.op} ${edge.loc} → (${now.x},${now.z}), now in ${landed}`);
    return "crossed";
  }
  log(`pass: ${edge.op} ${edge.loc} left the character in ${landed ?? "no area"} at (${now.x},${now.z}), wanted ${edge.to}` + ` — it said: ${GameMessages.since(mark).map((m) => m.text).slice(-3).join(" / ") || "nothing"}`);
  return "same";
}

// src/bot/api/ai/quests/defs/upass/stand.ts
function crossingLanding(at2, stand) {
  return new Tile(at2.x + Math.sign(at2.x - stand.x), at2.z + Math.sign(at2.z - stand.z), at2.level);
}
function bySideThatLands(at2, dest, me) {
  const toward = (tile) => Math.abs(tile.x - dest.x) + Math.abs(tile.z - dest.z);
  return (a, b) => toward(crossingLanding(at2, a)) - toward(crossingLanding(at2, b)) || chebyshev(a, at2) - chebyshev(b, at2) || chebyshev(a, me ?? a) - chebyshev(b, me ?? b);
}

