var HEARTBEAT_ATTEMPTS = 5;
var HEARTBEAT_MS = 15000;
var FAIL_WARN = 5;
function formatDuration(ms) {
  if (ms < 1000) {
    return `${Math.round(ms)}ms`;
  }
  if (ms < 60000) {
    return `${(ms / 1000).toFixed(1)}s`;
  }
  return `${Math.floor(ms / 60000)}m${String(Math.round(ms % 60000 / 1000)).padStart(2, "0")}s`;
}
function formatTile(tile) {
  return tile ? `(${tile.x},${tile.z}${tile.level > 0 ? `,L${tile.level}` : ""})` : "(no tile)";
}
function invDelta(before, after) {
  const names = new Set([...before.keys(), ...after.keys()]);
  const parts2 = [];
  for (const name of [...names].sort()) {
    const a = before.get(name) ?? 0;
    const b = after.get(name) ?? 0;
    if (a !== b) {
      parts2.push(`${name} ${a}→${b}`);
    }
  }
  return parts2.length > 0 ? parts2.join(", ") : "no inventory change";
}

class StepTracker {
  key = "";
  attempt = 0;
  since = 0;
  lastBeat = 0;
  open(key3, now) {
    if (key3 !== this.key) {
      this.key = key3;
      this.attempt = 0;
      this.since = now;
      this.lastBeat = now;
    }
    this.attempt++;
    return this.attempt;
  }
  attempts() {
    return this.attempt;
  }
  elapsed(now) {
    return now - this.since;
  }
  beat(now) {
    if (this.attempt <= 1) {
      return false;
    }
    if (this.attempt % HEARTBEAT_ATTEMPTS === 0 || now - this.lastBeat >= HEARTBEAT_MS) {
      this.lastBeat = now;
      return true;
    }
    return false;
  }
  reset() {
    this.key = "";
    this.attempt = 0;
    this.since = 0;
    this.lastBeat = 0;
  }
}

