function inJungleBand(tile) {
  return !!tile && tile.level === 0 && tile.x >= 2757 && tile.x <= 3006 && tile.z > JUNGLE_BAND.south && tile.z < JUNGLE_BAND.north;
}
function legendsArea(tile) {
  if (!tile) {
    return "unknown";
  }
  const { x: x2, z } = tile;
  if (x2 >= 2752 && x2 <= 2815 && z >= 9280 && z <= 9343) {
    return "shamanCaves";
  }
  if (x2 >= 2368 && x2 <= 2431 && z >= 4672 && z <= 4735) {
    return "viyeldiCaves";
  }
  if (z >= 4000) {
    return "unknown";
  }
  if (x2 >= 2757 && x2 <= 3006 && z >= 2882 && z < JUNGLE_BAND.north) {
    return "jungle";
  }
  return "mainland";
}
function inOctagram(tile) {
  if (!tile || tile.level !== 0) {
    return false;
  }
  const { x: x2, z } = tile;
  return x2 >= 2788 && x2 <= 2797 && z >= 9328 && z <= 9329 || x2 >= 2792 && x2 <= 2793 && z >= 9324 && z <= 9333 || x2 >= 2789 && x2 <= 2796 && z >= 9325 && z <= 9332;
}
function jungleSection(tile) {
  if (!tile || legendsArea(tile) !== "jungle") {
    return null;
  }
  if (tile.x <= 2815)
    return "west";
  if (tile.x <= 2879)
    return "middle";
  return "east";
}

// src/bot/api/ai/quests/defs/legends/scene.ts
async function offerTo(itemId, npc, log) {
  const item2 = Inventory.items().find((i2) => i2.id === itemId);
  if (!item2) {
    log(`nothing with id ${itemId} in the pack to offer`);
    return false;
  }
  if (!await Traversal.walkResilient(npc.tile(), { radius: 1, attempts: 2, timeoutMs: 30000, log })) {
    return false;
  }
  await settleScene();
  return item2.useOn(npc);
}
function here10() {
  return legendsArea(Game.tile());
}
var ENDED_TICKS = 10;
var NEVER_OPENED_TICKS = 25;
async function driveToEnd(prefer, log, ms = 45000, required) {
  const deadline = performance.now() + ms;
  let quiet = 0;
  let spoke = false;
  let took = false;
  while (performance.now() < deadline) {
    if (ChatDialog.canContinue()) {
      spoke = true;
      await ChatDialog.continue();
      await Execution.delayTicks(1);
      quiet = 0;
      continue;
    }
    const options = ChatDialog.options();
    if (options.length > 0) {
      spoke = true;
      const pick = pickPreferred(options, prefer);
      if (!pick) {
        log(`no preferred option in [${options.join(" | ")}]`);
        return false;
      }
      log(`chose "${pick}" from [${options.join(" | ")}]`);
      took = took || pick === required;
      await ChatDialog.chooseOption(pick);
      await Execution.delayTicks(2);
      quiet = 0;
      continue;
    }
    if (Modals.isOpen()) {
      spoke = true;
      if (!await Modals.close()) {
        await Execution.delayTicks(1);
      }
      quiet = 0;
      continue;
    }
    if (!ChatDialog.isOpen()) {
      quiet += 1;
      if (quiet >= ENDED_TICKS && spoke) {
        if (required && !took) {
          log(`the chain ended without ever offering "${required}"`);
          return false;
        }
        return true;
      }
      if (quiet >= NEVER_OPENED_TICKS) {
        log("no dialogue ever opened");
        return false;
      }
    }
    await Execution.delayTicks(1);
  }
  return spoke && !ChatDialog.isOpen();
}
function modalText() {
  return [...reader.mainModalTexts(), ...ChatDialog.texts()].join(" ").replace(/@[a-z0-9]{3}@/gi, " ").replace(/[|\s]+/g, " ").trim().toLowerCase();
}

// src/bot/api/ai/quests/defs/legends/gather.ts
var GEM_ROCK_ID = 2111;
var MINE_MS = 240000;
function uncutHeld() {
  return GEM_CUTS.reduce((sum, gem) => sum + heldId(gem.uncut), 0);
}
async function mineGem(log) {
  const before = uncutHeld();
  if (!await Traversal.walkResilient(LQ_TILE.GEM_ROCKS, { radius: 3, attempts: 3, timeoutMs: 240000, log })) {
    return false;
  }
  await settleScene();
  const deadline = performance.now() + MINE_MS;
  while (performance.now() < deadline) {
    if (uncutHeld() > before) {
      return true;
    }
    const rock = Locs.query().where((l) => l.id === GEM_ROCK_ID).action("Mine").within(10).nearest();
    if (!rock) {
      await Execution.delayTicks(10);
      continue;
    }
    if (await rock.interact("Mine")) {
      await Execution.delayUntil(() => uncutHeld() > before, 20000);
    }
    await Execution.delayTicks(1);
  }
  log("no gem in four minutes at the Shilo rocks");
  return false;
}
async function smeltGoldBar(log) {
  const before = heldId(LQ_ID.GOLD_BAR);
  if (heldId(LQ_ID.GOLD_ORE) === 0) {
    log("no gold ore to smelt");
    return false;
  }
  if (!await Traversal.walkResilient(LQ_TILE.FURNACE, { radius: 3, attempts: 3, timeoutMs: 180000, log })) {
    return false;
  }
  await settleScene();
  return useOnLoc(LQ_ID.GOLD_ORE, { name: "Furnace", near: LQ_TILE.FURNACE, within: 10 }, [], () => heldId(LQ_ID.GOLD_BAR) > before, log);
}
var BRAVERY_HERBS = [
  { unidId: LQ_ID.UNID_SNAKE_WEED, id: LQ_ID.SNAKE_WEED, name: "Snake weed", loc: "Marshy jungle vine", stand: LQ_TILE.SNAKE_WEED },
  { unidId: LQ_ID.UNID_ARDRIGAL, id: LQ_ID.ARDRIGAL, name: "Ardrigal", loc: "Palm tree", stand: LQ_TILE.ARDRIGAL }
];
function pickHerb2(herb) {
  return async (log) => {
    if (heldId(herb.id) > 0 || heldId(herb.unidId) > 0) {
      return true;
    }
    return promptLoc({
      name: herb.loc,
      op: "Search",
      near: herb.stand,
      expect: () => heldId(herb.unidId) > 0
    }, log);
  };
}
function identifyHerb2(herb) {
  return async (log) => {
    if (heldId(herb.id) > 0) {
      return true;
    }
    const unid = Inventory.items().find((item2) => item2.id === herb.unidId);
    if (!unid) {
      log(`no unidentified ${herb.name} in the pack`);
      return false;
    }
    if (!await unid.interact("Identify")) {
      return false;
    }
    return Execution.delayUntil(() => heldId(herb.id) > 0, 6000);
  };
}

